#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}


patchFile('siman_035/baer-heitev/part-001.txt', 'baer-heitev', {
  '2#א': `For the lung. Meaning: ona (lobe) — language of ear; and ama — language of mother, meaning the large one from which the onot separate, and it is the main lung; and ayinunita de-varda is so called on account of its delicacy and redness — Rashi on Chullin.`,
  '2#ב': `From the left. And Shach wrote: even if there are four on the right and one is missing on the left — treifah, unlike Torat Chaim who permits in this.`,
  '2#ג': `Treifah. And Shach wrote: and likewise also four on the left and three on the right is exchange and treifah.`,
  '2#ד': `And treifah. And Maharshal wrote: I am astonished at these treifos that Rama mentioned that were not mentioned in our Talmud except three on the right and two on the left, and he does not declare treifah except the exchange mentioned in the Talmud; and Bach wrote one should rely on Maharshal's words in a place of great financial loss. And so Pri Chadash: we permit in such a case. And if the middle ona is larger than the upper ona of the right — kosher. And likewise if on the right side there are four onot and on the upper ona there was a small ona and the middle ona was larger than the ona adjacent to the ama — kosher — end. And see in Sefer Einayim Yeshayim these laws. Responsum of Noda Biyehudah siman 55 wrote: minor loss is a chicken or dove weight, and anything more than that is great financial loss; and one whose heart misgives him — it appears to me that whatever he lost from capital slightly more than one-sixth is certainly great financial loss without doubt. And one may distinguish between poor and rich, for for him it is not great financial loss except beyond one-sixth — end. And Maharshal also wrote: if the varda is larger than the ona next to it — meaning the ona adjacent to the ama — treifah. And Taz wrote well: for its name is ayinunita, and if it is so large that name does not apply. And he also wrote: if the ama is above and the onot below — treifah; and Taz wrote: it appears to me that where there is another suspicious matter, even though one does not declare treifah on its account, nevertheless it combines with the suspicious matter above and it is treifah.`,
  '2#ה': `Two. Even if they do not stand one next to the other — Shach. And specifically when they have two pouches; but if one is placed in a pouch and the second is not placed in a pouch, even if the one in the pouch has no varda designation and the second has — kosher even for us (Darkei Moshe daf 106).`,
  '2#ו': `Vardot. And Taz wrote: and even though we hold in seif 3 that extra from the front is kosher, it must be said that here we declare treifah because all extra is considered as removed; and accordingly treifos of varda are only when both are in the place of the varda and do not have one root like finger-thickness after inflation; nevertheless if you find an extra ona inside, even in the place of the varda, there is no disqualification here for two vardot, for the form of the ona is not like a varda; and the same if two vardot are found, one on the right and one on the left — kosher, for "extra as removed" does not apply since the extra does not stand in its proper place — see siman 55 seif 4.`,
  '2#ז': `Missing. And Darkei Moshe wrote: if it is less than a myrtle leaf after inflation — treifah.`,
  '2#ח': `Its place. Meaning: its way is to stand below the onot and it has a groove; and when they inflate the lung the groove aligns opposite the cut between ona and ama, its back opposite the heart and its face opposite the kidneys; and if inverted so the groove is opposite the heart or its back opposite the cut — treifah; but if the groove is slightly inverted opposite the ona or below toward the ama — kosher — Mahariu. And Maharshal wrote: what of it if the groove is inverted — this is only loss of Jewish money and one should abolish this custom. And Pri Chadash wrote: he wrote well. See in later slaughter examinations; and Bach wrote: where there is no great financial loss one should not rule permission in what they practiced as forbidden.`,
  '2#ט': `Treifah. And Shach wrote in the name of Igur: if it has no groove like the designation of the varda — treifah; and if it is as large as the ona adjacent to the ama, or less than a myrtle leaf in inflation, or changed its designation that it is drawn out and sharp like an ona and not round — one should declare treifah; and Shach wrote: it appears to him that even if it is only as large as the middle ona of the right — treifah; however I have seen many examiners lenient in this matter and do not declare treifah except when it is as large as the ona adjacent to the ama; and it appears that even for those who permit extra from the front in seif 3, nevertheless if it changed its designation and is so large — treifah, for it is like a missing varda, for this is an ona and not a varda — end.`,
  '2#י': `Finger. And Shach explained: there is no distinction between large and small animal — one always measures finger-thickness; meaning finger-thickness — that is, the measure of the height of the root of both before they branch must be like a finger.`,
  '2#כ': `Crack. In the remaining root, even if both have varda designation — kosher — Maharam.`,
  '2#ל': `Inverted. Meaning: that they have one root; for if they do not have one root, even if both are not inverted — treifah, for these are two vardot.`,
  '2#מ': `Kosher. And Shach wrote: but if both are equal — treifah and not kosher unless the inverted one is smaller than the non-inverted; further it appears there from the words of HaRav that "changed its designation" has the law of inverted in this. If two vardot are pressed together we press according to our custom even on a thief to examine them.`,
  '2#נ': `Treifah. And the reason the acharonim wrote: because then it certainly changed the varda's place slightly; and Shach wrote in the name of Maharshal: even if it has no pouch — kosher; and all the more if it has two pouches or is not placed in a pouch; except that all examiners practice to declare treifah, and it is difficult to be lenient against the custom except in great financial loss; and regarding one who has two pouches he brings in the hagahah: specifically extra on the right side is treifah because all extra is considered as removed; and he wrote such is practiced in Krakow; and Maharam wrote there: and it appears to me that specifically when the pouch on the left has no part of the varda, for otherwise it is forbidden on account of extra varda; but from the words of Taz above it appears even in this it is kosher since it does not stand in its proper place, like regarding the leg.`,
  '2#ס': `Kosher. And Shach wrote: even for those who permit extra from the front, nevertheless for two vardot or missing or changed place — treifah. And the distinction by which we know which is extra varda and which is extra from the front: when it has a true varda designation, even if the extra stands on the left side — it is extra varda; but when it does not have a true varda designation in a matter that can be considered extra, one may permit since it does not stand in the place of the varda; and likewise even if it does not stand in its place and has no true varda designation but has a pouch by itself — it is recognizable that there are two vardot and treifah; but if it has no varda designation at all, even though it has a pouch — kosher. And Taz wrote: when two vardot are found — treifah; the reason is all extra is considered as removed; and accordingly it appears one should not declare treifah for two vardot except when both stand in the place where the varda should be and do not have a root like finger-thickness after inflation; nevertheless if you find an extra ona inside, even in the place where the varda should be, and it has no varda form — there is no disqualification here for two vardot, for the forms of the onot are not like a varda; and the same if two vardot are found, one on the right and one on the left — "as removed" does not apply since the extra does not stand in its proper place — see siman 55 seif 5. I found written in Knesset HaGedolah on koy that they call it boful and its way is to have two vardot, and so for most wild animals — and they are kosher; but for other laws they are like an animal regarding adhesion of vardot or varda designation and distance and inversion and all other treifos — only regarding extra of ayinunita we do not declare treifah in them. And Bach wrote: such a case came before him several times and he permitted; if it stands in the place of the varda itself I received from my master may he live long that they practice to declare treifah if it has some varda designation; but if it resembles an ona itself one may consider it extra from the front; and if it has one root — see above in this seif. And what Rama wrote regarding missing part of the varda that one should examine the ama of the left — there is a correction to right; and so in Torat Chaim, for if ayinunita is found on the left side — treifah; and Shach rejects his words — see there.`,
  '2#ע': `And lambs. And Shach wrote: from this language it appears at first glance that even in a large animal the law is thus, since it is sometimes found in kids and lambs; but in the gloss HaRav brought it states: and specifically in kids and lambs, but not in a large animal. And regarding the law HaRav wrote there on this: we do not practice thus except that in every change of place we declare treifah, even in kids and lambs; and it appears the reason: since it is attached to the ama it is merely extra and ayinunita de-varda has nothing; and if there is a pouch on it — then it is certainly a varda; but it is a varda by itself. And according to Taz from what he wrote in s.k. 4 it appears kosher if there is another varda on the left side. And he also wrote: R' Liberman the slaughterer of Prague wrote in his examinations that ayinunita requires varda designation, and if it has no varda designation it does not matter according to Mahariu; and in my opinion if he practiced thus he fed treifot to Israel all his days, for I already wrote in the name of all poskim that if it has no varda designation — treifah; but in truth these laws do not contradict each other at all, for I received from my master: when part of the varda is missing and found thus in an ona or ama, they combine and it appears there is varda designation between both; and such Maharam wrote: if two vardot are found with one root not like finger-thickness and no varda designation except through combination — they permit, for it is considered one; and further regarding what remains there is varda designation, as Rama wrote; and so there are those who permit if it has varda designation at its root, etc.`,
  '2#פ': `Its place. And Shach wrote in the name of HaRav: if it has one root, even though it became small and nothing remains — nevertheless kosher; and Shach also wrote that in examinations he disputes this law and it is an error, for Rama's words are primary.`,
  '2#צ': `Matter. This does not refer to missing or two vardot or changed place — these treifos were mentioned in Rashi and Tosafot; rather it refers to the other laws Rama mentioned — Taz. They practice not to eat the varda because of repulsiveness; nevertheless if it was salted with other meat it is permitted — so from a received tradition. If the varda was found perforated, even though its pouch seals it — treifah — see there siman 16, etc. And that two pouches are treifah — specifically when they have one wall between them; for if we say extra is considered as removed, there is no pouch at all; but distant from each other, each has a pouch by itself — kosher — Knesset HaGedolah. And I heard from an expert examiner: specifically when the ayinunita benefits from both, such as they stand one next to the other and the varda is placed in both; and also each pouch has a ligament at its edges on the lip — and if one of all these is missing — kosher — see there daf 95. If the varda's pouch is tight so the varda cannot exit except through opening, even though there is no adhesion or blister — treifah, and inflation does not help — so from a received tradition daf 173. And Shach wrote in the name of Maharshal in examinations: all they wrote to be lenient, whether in exchanges not mentioned in the Talmud or in the size of ayinunita de-varda — that is only when there is no other healthy suspicious matter; but if there is suspicious matter, even in a matter we permit, nevertheless since there is a side of stringency to declare treifah for someone, even not according to the law, nevertheless in anything it combines to support the forbidders, and we say it is a weakness and treifah.`,
  '3#_': `Treifah. It appears from the words of the poskim that if extra is found one must inflate to see whether it leans forward or toward the back — Shach. And Shach also wrote: and specifically a protruding extra like tarfa de-asa; but if it bent and goes upward — kosher, since it stands in a permitted place — because it protrudes outward it is not declared treifah (and if extra is found in a bed that is above the onot adjacent to the spine inside the lung, I found written that it is kosher). And it appears to me treifah, for this is certainly included more in "on its back" that the Talmud mentioned — Taz.`,
  '5#א': `Kosher. And Shach wrote: and likewise more than tarfa de-asa (what he wrote "because its way is to split" means because of the narrowness of the chest) — Maharam.`,
  '5#ב': `Treifah. And Taz wrote in examinations there are two explanations on this. One: the half is toward the tip of the ona; but if found toward the root of the ona — treifah; and accordingly this measure of half is in the width of the ona. And some say one also measures in the length of the ona — that is, that half in width that we permitted is not all of it but specifically half its length — that is, opposite the windpipe; but not the other side toward the lung; and so Maharshal explained, and one should be stringent like the latter view (and we practice measuring thus: they take the ona of the left and place it next to the upper ona of the right, and from where the left ona ends onward is called the tip side — that is, toward the head — and kosher; and from where the left ona touches toward the lung is called below, and if the split is there — treifah) — Einayim Yeshayim.`,
  '5#ג': `Kosher. And Maharshal wrote: what he wrote in Likutim that one may not permit if five are found on each side is foolishness, and if it comes before me I will buy the finest from it — end (and in the hagahah of Mahariu they declare treifah, and Maharshal and Bach permit, and Pri Chadash wrote: I say that whenever on the right side there are three onot as required, what does it matter if there are more on the left, for it is not called exchange unless there is deficiency on the right; therefore one who is lenient did not lose — see there and in Beit Yosef).`,
  '5#ד': `To declare treifah. And Shach wrote: if three onot are found on the left and a crack — it is not like four onot; and it implies that even one healthy one combines to permit but not to declare treifah — for example if on the left there is one ona and three cracks, we say one crack helps to permit and the others count for nothing to consider exchange to declare treifah; and we do not say either way; rather we are not concerned about cracks at all to declare treifah; however Taz wrote: if on the right there are two onot and a crack and there is another suspicious matter on the left — that is, there are three onot on the left — one should declare treifah (and R' Yosef ruled to permit, and Maharshal and Bach forbid, and Pri Chadash wrote this is not primary but one may permit simply, and so R' Yosef and Shach in Knesset HaGedolah).`,
  '5#ה': `It. And Shach wrote: meaning specifically to declare treifah; but to permit it is no worse than a crack which is kosher.`,
  '5#ו': `And kosher. And Shach wrote: and likewise if round above — also kosher; but if found above or below sharp like a cap — it is extra and treifah — Beit Yosef and Darkei Moshe.`,
  '5#ז': `And kosher. For the same applies when it reaches the animal's walls it descends into the hollow and need not rub against the wall — kosher — Maharam. And Taz wrote: but if shorter than the hollow — treifah, for then it is not a split but extra (and Pri Chadash and Shach in Knesset HaGedolah disagree with Taz, for even if it is extra, nevertheless there is doubt it will not come apart; rather it comes to exclude when it was longer than the hollow — then treifah).`,
  '5#ח': `And treifah. And Shach wrote: and it is not similar to extra from the front which is kosher, for there the extra is of the ona and it is strong; but a split that split from the body of the lung will eventually come apart and is treifah; but if there is no hollow beneath it, our custom is to permit, for this is extra from the front — Shach, Taz; and Einayim Yeshayim wrote: one must know that a split is treifah only when it is like tarfa de-asa specifically after inflating the lung, for when it is so large then certainly it will come apart; but extra on a bed is treifah even when not as large as tarfa de-asa, since it rubs against the ribs — see there in the law of split siman 1 and siman 4.`,
  '5#ט': `Great loss. And Shach wrote: all this is according to those who forbid extra from the front; but in a place where they permit, it is obvious this too is kosher — end. And it requires further study: for behold split from the front is treifah even if extra is kosher, as written above; therefore it is difficult on Rama who wrote its law is like a split with a hollow and one should not rely on this, etc.; and it is possible he holds that since it stands opposite the groove and the groove protects it, its law is like a split with a hollow from the back — and it requires further study.`,
  '7#א': `Completes. And Shach wrote: but on the left, if one ona is missing, even if varda is found on the left it does not complete — so all hold; and Bach disagrees.`,
  '7#ב': `Custom. And the reason is in Shach: because it does not stand in the row of onot; even though we hold extra from the front is kosher; and accordingly even extra of an ona from the front does not complete; also one may declare treifah and say it does not complete, for if so it is missing varda and treifah — see Darkei Moshe daf 107. And Taz wrote s.k. 13: if extra is found in a bed above the ona adjacent to the spine inside the lung — it is kosher; and it appears to me treifah, for this is certainly included more in "on its back" mentioned in the Talmud (and he also wrote what Rama wrote regarding two vardot with one root that is like finger-thickness — even though there is no finger-thickness there; and a certain sage wrote: nevertheless we require the length of the root like a finger between the two vardot; and it appears to me the measure is the height of the root of both before they branch must be like a finger).`,
  '8#א': `Treifah. And Taz wrote in the name of Maharshal: there was an incident in Rinus where they slaughtered a fat cow and when they examined it they found no lung — neither ama nor ona nor varda nor any crack, only it was smooth like one piece of meat; and there was one examiner who was prominent among the sages of Austria; he took a sharp knife and cut the upper membrane — that is, the upper garment and covering that had formed on it — and opened it gently and peeled it gently and separated it all from above; then they saw the lung like other lungs and permitted it; and he said he saw such a case in Austria — see end of this section 39.`,
  '8#ב': `Kosher. And Shach wrote: and specifically when the crack stands in its proper place; but other cracks do not help — end Maharam and Maharshal; and if the ona next to the ama is missing somewhat and the ama is larger than usual and when they inflate the lung it fills the deficiency and will be equal as it should — kosher; but if it was smaller than usual — treifah — Darkei Moshe daf 108 — see there more of these laws.`,
  '8#ג': `To declare treifah. And Maharshal divides and holds: if entirely attached, then where there is some sign we see that thus they grew; but for a missing ona we do not permit with a crack, only when it is of the measure of tarfa de-asa; and Shach disagrees and agrees with Rama's words that there is no distinction — one always permits with a crack — and so Bach.`,
  '8#ד': `And kosher. And Taz wrote: the same between ona and ona these signs also help.`,
  '8#ה': `Sign. And Maharshal disagrees with all these signs and does not permit if a distinction like tarfa de-asa is seen; and Shach wrote one should not be stringent except when entirely attached like a sponge; but when the lung is as it should be except two onot are attached together, one may permit through simpun; and in Hagahot HaRav he divides: specifically from ona to ama simpun helps and other signs, but not from ona to ona — in this other signs do not help, not even simpun; and other hagahot disagree that their law is equal, and such is primary — Taz.`,
  '8#ו': `With them. And Shach wrote: one may not permit unless within thirty days of birth with certainty; and also they follow the mother who nurses them — both are required; but after thirty days, even though they follow the mother and she nurses them, they are considered adults — Pri Chadash wrote one should not rely on these views; but from doubt we say it is after thirty days. And he also wrote: if on one side of the lamb it has onot as usual and on the other side it does not — one should declare treifah even in kids and lambs.`,
  '9#_': `Practice. And Shach wrote: it is not similar to what was written in seif 4 that if found at the end of the slopes of the ama it is kosher — it is different there, for the onot are as they should be and it is like extra in the row of onot; but for one missing ona this protrusion does not complete the deficiency; and Bach wrote: a case came before him several times — a lung with no suspicious matter except on the left a protrusion emerged from the ama at the cut between ona and ama exactly where the varda usually stands opposite on the right; and that protrusion had a complete pouch and was placed in it and had no varda form at all (and was equal to the ama on the front side) as if cut from it; and he permitted it because that protrusion was neither extra from the front nor extra varda and there is no suspicious matter except from the pouch, and there is no logic to forbid it for this — end. And Taz wrote on this: it appears to me even if it had varda form there is no prohibition here, for it is called extra from the front and kosher for us; and prohibition of two vardot is only when both stand on the right in their proper place and are not like finger-thickness between them; and the pouch certainly does not forbid, for we do not find that because of a pouch extra there is prohibition (however it is difficult, for he wrote above he forbids two pouches — and it is possible this refers specifically when it is in the place of the varda — examine). And Maharshal wrote: if the lung's extra stands in the row of onot and leans slightly outward through inflation — treifah; but Beit Yosef wrote: specifically protruding extra, but if bent and goes upward — kosher since rooted in a permitted place — end.`,
});

patchFile('siman_035/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Mishnah Chullin daf 42.`,
  '2#_': `Statement of Rava there daf 47.`,
  '3#_': `From that incident before Rav Ashi, etc., there.`,
  '4#_': `End of the statement there (°) meaning: the language "if" — for it is the main part of the lung.`,
  '5#_': `Rosh there in the name of the Geonim; and Ran wrote it appears this is the view of Ri"f and Rambam in chapter 8 of Hilchot Shechitah; and so Rashba in Teshuvot; and so Tur.`,
  '6#_': `Conclusion of the Gemara there.`,
  '7#_': `Rambam there from the implication of the Gemara that says "but from the back," etc.; and Ran wrote thus appear the words of Ri"f; and so Rashba.`,
  '8#_': `Tosafot; and so Avi HaEzri and Rambam there; and Rosh there; and so Ran in the name of Ramban.`,
  '9#_': `Incident before the Rav Beit Yosef; and as he inferred from Rambam's wording there; and so Rashba in Teshuvot (siman 420).`,
  '10#_': `Mordechai in the name of Ravyah who heard from his father.`,
});

patchFile('siman_035/beur-hagra/part-001.txt', 'beur-hagra', {
  '2#א': `When the animal, etc. — Rashi.`,
  '2#ב': `Forms, etc. — all this is included in exchange.`,
  '2#ג': `And the varda: if missing. From R' Eliezer's view to declare them treifah — we learn it is not their way thus — Rashi.`,
  '2#ד': `Or if, etc., or if, etc. — it should only be extra and kosher from the front, as written below.`,
  '2#ה': `And in lands, etc. — that it is included in missing, since its way is to be in all animals.`,
  '2#ו': `Whether, etc. — as Nachmanides wrote: all extra, etc.`,
  '2#ז': `Or if it changed its place — that Tosafot and Ran challenged on what was said there "that between and between," etc., what of "between and between" is treifah; and they wrote: for example when its form is not like a varda or not in its place; and this is also what he said below: and likewise if it changed its designation, etc.; and even though all this is according to those who forbid extra from the front, nevertheless even for those who permit — missing varda.`,
  '2#ח': `If, etc., and there are, etc. — as written regarding kids — Nachmanides 2.`,
  '2#ט': `Even though, etc. — meaning in that root; for we are not concerned about cracks to declare treifah, as written in seif 8 in the hagahah.`,
  '2#י': `And if one, etc. — it refers to one root — Shach.`,
  '2#כ': `The varda's way, etc. — he holds all this is included in changed its form.`,
  '2#ל': `Or if it has, etc. — likewise because all extra, etc.`,
  '3#א': `If onot were added, etc. — as written there; and this applies from inside; but from the fact he did not distinguish "from inside" itself — we learn that from inside in every case is kosher.`,
  '3#ב': `And it, etc. — from what he wrote "even like tarfa de-asa," etc., and it implies specifically like tarfa de-asa, as written in chapter 2 of Berakhot (15a) and chapter 3 of Pesachim and chapter 9 of Chullin — and from it is the matter that it does not return, etc. (Likut). But if it, etc. — even though he said "even," he means specifically, as written in chapter 2 of Berakhot and from it is the matter, etc., and in chapter 9 of Bava Batra (146a) "Rav said: specifically a dinar," etc. — Tosefet HaRav (end).`,
  '3#ג': `And some are stringent, etc. — as explained: but "between and between," etc., and he did not say "and it is not so," for that "between and between," etc. — evidently he did not retract from the first reasoning; and that which he said "and this applies from inside" — he did not wish to elaborate and distinguish within inside itself, and he stated a decided matter.`,
  '4#_': `If found, etc. — even for those who forbid, extra from the front is permitted, as explained in the hagahah — Beit Yosef.`,
  '5#א': `That which we permit, etc. — for otherwise it is exchange.`,
  '5#ב': `And if seen, etc. — for even regarding sponge we permit, as written in seif 8.`,
  '5#ג': `An ona that split, etc. — as explained above in seif 2; and specifically to permit, as explained.`,
  '6#_': `One of the onot, etc. — from what he wrote "even like tarfa de-asa," etc., it implies that less than this is as if it does not exist.`,
  '7#א': `Missing, etc. — see Bach, and he means that according to his view extra from the front and the row of onot are one matter.`,
  '7#ב': `And some say, etc., and such is the custom. And not from their reason that they hold extra from the front is invalid — rather he forbids because of missing varda — and examine.`,
  '8#_': `The lower ona, etc. — for in any case it leaves the category of sponge, for sponge has no sign at all — there.`,
  '9#א': `If on one side, etc. — as explained above in seif 4.`,
  '9#ב': `And there are those who practice, etc. — it implies specifically here — Pri Megadim and Shach.`,
});

patchFile('siman_035/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `A) [Seif 1] A lung that was perforated — treifah, because wind exits there and it cannot live. Levush. Zivchei Torah ot 1.`,
  '2#_': `B) There. A lung that was perforated — treifah; and the law of a perforated lung is explained below siman 36. And the reason the Mechaber wrote this seif here is to say that the reason for the treifos arranged in this siman is on account of perforation of the lung. Pri Eitz Chaim ot 1; Zivchei Torah there.`,
  '3#_': `C) And know that the lung flutters to the heart so it not burn from natural heat; and the lung is like an inflated wineskin — if a small hole is pierced in it, all the wind exits there and it remains as dead; and thus it cannot flutter to the heart and will burn and die; and even though this hole is already sealed by adhesion or a blister or an invalid appearance, and similarly for the other lung treifos explained in these simanim — nevertheless the question is: a scab that arose from a blow is nothing, for ultimately it will peel and the hole remain open, as below siman 36 seif 3; and this is the reason for all lung treifos. Shulchan Gavo'ah ot 1.`,
  '4#_': `D) A lung that was perforated — treifah. Hilchot Melichah; and all lung treifos in these simanim are all on account of being perforated, for the Sages held that if it was struck by one of those lesions, ultimately it will be perforated; and whatever is destined to be perforated is considered as perforated; therefore all treifos explained here are so. Shulchan Melachim ot 1; Chokhmat Adam kelal 9 ot 1; Beit Yitzchak ot 1; Kometz HaMinchah head of the siman.`,
  '5#_': `E) [Seif 2] Five lobes the lung has, etc.; and below are two large "mothers," one to the right and one to the left. And "lobes" (onim) means ears, for the translation of ear is oni; and ama is called the large one — from the word mother — from which the lobes separate, and it is the main lung. So Rosh regarding two adjacent lobes in the name of R' Tam; and lobes and ama are all called lung; and some explain it is called lung because one sees and examines it in inspection. Perishah ot 1; and in the Gemara Perek Eizehu Mekoman daf 47a they say: why is it called lung (re'ah)? Because it enlightens (me'irah) the eyes — meaning, one who eats it, through the signs that enlighten the eyes, it too assists them. Knesset HaGedolah in Hagahot Turei Zahav ot 4.`,
  '6#_': `F) There. And it is called ayinunita de-varda. Like a small ona (lobe) of varda, on account of its delicacy and redness. Rashi Chullin 47a. Taz s.k. 1. Shach s.k. 2.`,
  '7#_': `G) There. And if one is missing from the right or from the left, etc. — even if there are four on the right, if one is missing on the left — treifah. Shach s.k. 3. Knesset HaGedolah there ot 11. Pri Chadash ot 3. Pri Eitz Chaim ot 2. Lechem HaPanim ot 4. Beit Lechem Yehudah ot 3. Kereti ot 1. Shulchan Melachim ot 23. Levush ot 40. Sha'arei Tzedek ot 3. Zivchei Torah ot 4. Beit Yitzchak siman 35 chavot da'at ot 1. Kometz HaMinchah siman 35 ot 2. Sha'arei Shamayim end ot 2 and in his book Einayim Yeshayim siman 9 ot 2. Zivchei Tzedek ot 1.`,
  '8#_': `H) If the ama is missing — treifah, whether from the left or the right. Turei Zahav ot 2. Mishnat Zekenim ot 2. She'erit Yosef ot 5. Or HaChaim ot 2. Sha'arei Shamayim ot 3. Einayim Yeshayim there ot 3. Amrei Tov on examinations of Mahariu ot 4. Zivchei Shem ot 15. Zivchei Tzedek ot 2.`,
  '9#_': `I) There. Or if there were two on the right and three on the left — treifah; and likewise four on the left and three on the right is exchange and treifah, as the Rav wrote in the hagahah seif 5. Shach s.k. 4. And see below ot 84.`,
  '10#_': `J) There, hagahah. The forms of the lobes of the right are not like those of the left, and if their form was exchanged — treifah, etc. — all this is called exchange and treifah. But R' Shlomo in Yeshu'ot Shelomo Piskei Tosafot siman 54 wrote that all these are not called exchange and are kosher; and so Pri Chadash ot 5, Pri Eitz Chaim ot 3, She'erit Yosef ot 6, Zivchei Torah ot 6; and so Shulchan Gavo'ah ot 6 — in his place the Sephardim do not practice thus; and so Zivchei Tzedek ot 4 — custom in Baghdad, see Einayim Yeshayim, to permit all these exchanges like R' Shlomo and his supporters; and Ashkenaz custom is written in the ot that follows.`,
});

patchFile('siman_035/kereti/part-001.txt', 'kereti', {
  '2#א': `Or from the left: and if on the left there is one and four on the right — also treifah, for this too is included in exchange and missing on the left side — Shach and Pri Chadash, unlike Torat Chaim.`,
  '2#ב': `Two on the right, etc.; and likewise three on the right and four on the left is exchange and treifah.`,
  '2#ג': `All this is called exchange; and Maharshal and most acharonim wrote to permit one in a place of great financial loss — see Peleti: one should be moderate in this and not breach the fence of stringency received from the geonim — God forbid to say they erred.`,
  '2#ד': `And the varda: if missing — this is Rambam's view, who holds it was not received among Chazal that there must be a varda; therefore if missing or extra there is no concern, even if they do not stand one next to the other — all kosher.`,
  '2#ה': `If two vardot are found — Taz gave the reason: certainly extra from the front is kosher, only this is extra varda and it is like missing varda; and see Peleti where I elaborated and debated Rambam's words — see there.`,
  '2#ו': `Or if missing: and if it is less than tarfa de-asa — kosher. Changed place: its way is to stand below the onot and forward; and the groove in inflation is between the cut of ona and ama; and if the groove is inverted so its height is opposite the cut and the groove opposite the heart — treifah — so Mahariu and Maharshal; and Pri Chadash disagrees — it requires further study.`,
  '2#ז': `Changed its designation — it is like missing varda, since it has no varda designation and must be round like a rose and not sharp; and also not as large as the ona adjacent to the ama, for the Gemara language "and it is called ayinunita de-varda" only teaches that designation is required like a rose.`,
  '2#ח': `Like finger-thickness — and it is like below siman 16 regarding intestines, etc.; and there is no difference between large and small.`,
  '2#ט': `In it a crack in the root; and likewise both have varda designation.`,
  '2#י': `And if one is inverted, etc. — meaning one root; but with two roots, even if neither is inverted at all — treifah — Shach.`,
  '2#כ': `Treifah — for certainly the varda changed its place.`,
  '2#ל': `Some say kosher, for such is the custom of our rabbis, even though varda should be on the right — what of it if there is somewhat on the left, or it is missing and the designation was lost; nevertheless since its way is to be thus, one should not be stringent; and it appears they rely on this, since in any case all these matters are stringencies and many poskim permit.`,
  '3#א': `And when they inflate — it implies one must inflate the lung when extra is found, for it is suspicious.`,
  '3#ב': `And if it leans toward the back — treifah — Beit Yosef's view: if the root is in a permitted place, what of it if it bends and goes upward; and many forbid if the protrusion leaning outward is like tarfa de-asa.`,
  '4#_': `At the end of the slopes of the ama — not because it is extra from the front, but because it is in the row of onot; and for all, even those who forbid extra from the front, this is kosher.`,
  '5#א': `That which we permit, etc. — and Pri Chadash also in this his view is to permit, since there is a count — behold on each side; and see Peleti: in a place of loss one may rely on him.`,
  '5#ב': `If they are equal on each side — even five on each side according to the acharonim, unlike the hagahah of Mahariu.`,
  '5#ג': `And not to declare treifah: and if one ona is found on the left with three cracks, we say to permit, for it is as if there are two and not as if there are three; and the reason: most animals have two on the left, therefore we say presumably this crack is for an ona by itself to equalize it with the majority of the world that mostly have only two.`,
  '5#ד': `Only one — meaning to declare treifah; but to permit it is no worse than a crack — Shach.`,
  '5#ה': `Wide below — it appears it is only a lump from the lung.`,
  '5#ו': `Into the hollow — and even if it does not fill the entire hollow; but if it is larger in quantity than the hollow — treifah — Nekudot HaKesef and Pri Chadash.`,
  '5#ז': `But from the front — the split is from the body of the lung and falls downward and will come apart; and it is not similar to extra from the front, for it is not from the body of the lung and "eventually will come apart" does not apply.`,
  '5#ח': `And treifah — see Peleti what he wrote here, for it is difficult from the Gemara "lung perforated or missing."`,
  '7#א': `But on the left it does not complete, even though the varda is also on the left; and Bach disagrees.`,
  '7#ב': `That it does not complete — and extra from the front also does not complete — Shach; and see Peleti that in my view a split on the upper onot combines to complete, for it is no worse than a crack.`,
  '8#_': `No cut of a lobe — treifah — see Peleti where he challenged: for in any case it is missing from the count of onot; and what does the Gemara teach us here that it resembles sponge; and if there is a crack, in any case it is kosher — see there and examine.`,
  '10#_': `But in a bird — see Peleti what he wrote there in explaining the Gemara.`,
});

patchFile('siman_035/kol-yaakov/part-001.txt', 'kol-yaakov', {
  '1#א': `A) They practice regarding the lines (shitin), etc.; and so is according to the kabbalistic tradition of the Ari z"l in Sha'ar HaKavanot in the drushim of tefillin drush 1; and regarding the division of the heads of the lines see Tur and Beit Yosef; and we shall write the division of the heads of the lines that the Ari z"l wrote in the aforementioned gate, for such is our custom; and this is his language: In the parshiyot of Rashi — parshat Kadesh, its four lines are these: "Vayedaber," "Mizeh," "Bachodesh," "Betzeiti"; parshat Vehayah ki yeviacha, four lines: "Vehayah," "Vechol peter," "LaHashem," "Peter rechem"; parshat Shema, four lines: "Shema," "Nafshecha," "Levanecha," "Le'ot"; parshat Vehayah im shamoa, four lines: "Vehayah," "Venatati," "Yevulah," "Beshovtecha"; parshiyot of Rabbenu Tam — parshat Kadesh, seven lines: "Vayedaber," "Et hayom," "Bachodesh," "Zivchat," "Et sheva," "LaHashem li," "LaHashem mimitzrayim"; parshat Vehayah ki yeviacha, seven lines: "Vehayah," "Rechem," "Ve'im lo," "Zot leshalchanu," "LaHashem kol," "Einecha"; parshat Shema, seven lines: "Shema," "Et," "Me'odecha," "Hayom," "Beveitecha," "Le'ot," "Al mezuzot"; parshat Vehayah im shamoa, seven lines: "Vehayah," "Uvchol nafshechem," "Ve'achaltem," "LaHashem bachem," "Asher Hashem," "Bein eineichem," "Beitecha" — end of his words.`,
  '1#ב': `And now we shall explain the kavanah of the parshiyot and the lines and the writing of the Names from the Ari z"l, may his memory be blessed, according to the order arranged by the Rashash z"l, may his memory be blessed.`,
  '1#ג': `In general, the four letters of Havayah — one should intend the light of the Ein Sof that spreads from level to level and builds and repairs these aspects through the power of the burning flame (bozina de-kardunuta).`,
  '1#ד': `In the point of the upper yod one should intend the chaining of the light of the worlds and Arich Anpin, and Atik, and the keter of Arikh Anpin, and the keter of Abba.`,
  '1#ה': `And in general the yod — one should intend Atik and Arikh Anpin and the hidden brain (mocha setima'ah).`,
  '1#ו': `And in the three points of the yod: in the upper point — for the keter and da'at of Abba made from the keter and da'at of Chochmah of Abba of Ze'ir Anpin; and the keter of Imma made from the keter of Binah of Imma of Ze'ir Anpin; and the keter and da'at of Yisrael Saba made from Tiferet and Yesod of Abba of Ze'ir Anpin.`,
  '1#ז': `And in the second middle point one should intend the Chochmah of Abba made from the Chochmah of Chochmah of Abba of Ze'ir Anpin.`,
  '1#ח': `Also for the Chochmah of Yisrael Saba made from the Chochmah of Abba of Ze'ir Anpin.`,
  '1#ט': `And in the third point one should intend the Binah of Abba made from the Binah of Chochmah of Binah of Ze'ir Anpin; also for the Binah of Yisrael Saba made from the gevurot of Binah of Ze'ir Anpin; and the two letters vav-dalet of the filled yod — one should intend the ten sefirot of Imma, for the letter vav is the ten upper sefirot made from chesed-gevurah-tiferet and netzach-hod-yesod of Chochmah of Ben; and the letter dalet is Malchut made from the Malchut of Chochmah of Ben — all this is the right line of Arikh Anpin, and it is the name 72 yod-hei vav-hei.`,
  '1#י': `And in the first heh of Havayah one should intend the totality of the first and second Yisrael Saba made from Binah and Malchut of Binah of Imma of Ze'ir Anpin and Nukva and Malchut of Binah of Ben, and they clothe the left side of Arikh Anpin from the throat to the navel — and it is the name 63 yod-hei vav-hei.`,
  '1#כ': `And in the vav one should intend the six extremities of Imma and of Ben, and they are Ze'ir Anpin — and it is the name 45 yod-hei alef vav alef hei.`,
  '1#ל': `And in the final heh one should intend the Malchut of Imma and of Ben — she is Nukva — and it is the name 52 yod hei hei vav hei hei.`,
  '1#מ': `Also one should intend that the yod is the totality of Abba and the lower point of the yod hints and includes Imma.`,
  '1#נ': `And the two letters vav-dalet are the hidden Ze'ir Anpin and Nukva still in the drop of Abba. Also one should intend that the yod includes Chochmah-Binah-Daat; and the letter vav is the seven lower; and the dalet is Malchut. Also one should intend that the letter yod is ten sefirot of direct light (or yashar) and vav-dalet are ten sefirot of returning light (or chozer). Also one should intend in the chesed and gevurah in Da'at of Ze'ir Anpin, Shemen Sasson chapter 3 on drush 1 of tefillin; and see in Nefesh HaChaim daf 5 side 3 in the niddah section and what the Rashash z"l wrote in Sha'ar Einayim chapter 6 and understand; and one must also examine what is written below siman 476 ot 6 regarding the order of drawing down the letters of the Name at the time of writing and the kavanah I wrote there — and both are words of the living God, except that this kavanah here is more detailed, and I wrote it so that one who has more knowledge in the words of the Rav z"l may intend through it.`,
  '1#ס': `And a person must be careful when writing the Name not to interrupt — in thought, speech, or action — for he damages above and below according to the kavanot mentioned in the laws of tefillin, separating and cutting in plantings, God forbid, for all is bound like a flame in a coal; see there in the laws of writing; and further see in Sefer Kaf HaChaim siman 98 ot 3 and examine.`,
  '1#ע': `Before he writes he should say`,
  '1#פ': `"May it be pleasant" from beginning to end; and afterward he should say Ana Bekoach, etc., with great kavanah; and afterward say three times this verse: "They shall not hurt nor destroy in all My holy mountain, for the earth shall be full of the knowledge of Hashem as the waters cover the sea"; and afterward say these four verses [whose acronym is PASTAM]: "Turn to me and be gracious to me; give Your strength to Your servant and save the son of Your maidservant"; "I hate vain thoughts, but Your Torah do I love"; "Make me to hear joy and gladness, that the bones which You have broken may rejoice"; "How precious is Your kindness, O God, and the children of men take refuge in the shadow of Your wings."`,
  '1#צ': `May it be the will before You, Hashem our God and God of our fathers, that You act for the sake of Your great Name PASTAM which equals the numerical value of tefillin; and guide me in Your truth and in Your wondrous secrets and reveal Your hidden things in the glory of Your strength in which the son of Israel glories; and send openings of forgiveness from Your goodness to Your servant the son of Your maidservant so-and-so; and let Your Shechinah dwell in the work of my hands; and grant me success in writing this that I write tefillin for the sake of the sanctity of the mitzvah of tefillin that You commanded us, Hashem our God; and save me from error of kavanah and error of writing for the sake of Your Name and for the sake of the sanctity of the four parshiyot of the tefillin and their verses and words and letters and vowel-points and cantillation and their names and the names of the holy, pure, and awesome that issue from them — that this hour be an hour of favor, hour of mercy, hour of listening, hour of hearkening; and I will call You and You will answer me; I will supplicate You and You will accept me; and nullify from me all evil thoughts from the other side that arise in my thought at the time of writing and repair of the tefillin; and act for the sake of Your great Name KRA SHaTAN BaSHKaMaLV ANaSV; and likewise may it be the will, Hashem our God and God of our fathers, act below for Your great and holy Name that is in the world of Asiyah yod-hei hei vav hei hei; and for Your great Name in the world of Yetzirah yod-hei alef vav alef hei; and for Your great Name in the world of Beriah yod-hei vav-hei; and for Your great and exalted Name in the world of Atzilut yod-hei vav-yod hei — that my prayer be accepted before You like a burnt offering ascending and descending; and let there be no cause or hindrance in my work in this work of tefillin — neither error of kavanah nor error of writing — so as not to mislead me, accuse me, or incite against me — not any shell or other side nor any of their camps — that there be no cause or hindrance to confuse my thoughts and ideas; and influence upon me abundance from the supernal spring from the world of Atzilut to Beriah, from Beriah to Yetzirah, from Yetzirah to Asiyah, from Asiyah to the world of the spheres; and from there influence a spark of Your awesome and wondrous lights upon Your servant so-and-so, that he be blessed from Your great goodness, to unify Your Name and magnify the greatness of Your mitzvot that You commanded Your people Israel in Your holiness — blessed are You Who hears prayer: see there in the laws of tefillin; and so Maharach in the tikun of tefillin chapter 1 ot 3 and ot 4.`,
  '1#ק': `And one should further intend in the name David-Tiron whose numerical value is 239, the good inclination, with the eight letters — and it is the vowelling of the daletin in patach and kamatz, and likewise reish-vav in cholam and tet-yod in chirik — Maharach, name of the letter dalet.`,
  '1#ר': `Afterward, before writing, one should intend that all the verses of the four parshiyot of Rashi are in the numerical value of the name El that issues from the name 63, which is three yods and one — thus yod-yod-yod-alef-yod; and also corresponding to the name El that issues from the name Eheyeh in filled yods, which also has three yods and one — thus alef-yod-yod-yod; and in the four parshiyot of Rabbenu Tam one should intend in the name El that issues from Eheyeh in filled yods as above, and also in the name El that is in chesed, as it is written: "the kindness of God is all day long."`,
  '1#ש': `Also one should intend that all the havayot in the four parshiyot of tefillin are twenty-one like the numerical value of the name Eheyeh, as written in Sefer HaKavanot drush 2 of tefillin and Pa'aneach Razah, Sha'ar HaTefillin chapter 14 — see there.`,
  '1#ת': `Order of writing Rashi: At the beginning one should intend the simple Havayah that includes all four parshiyot in the tefillin of Rashi and the 72 Names drawn from it, and also the four names 161, 143, 151, and the full name Adonai, thus:`,
  '1#23': `YHVH`,
  '1#24': `y — yod hei vav hei alef hei yod hei`,
  '1#25': `h — yod hei vav hei alef hei yod hei`,
  '1#26': `v — yod hei hei vav hei alef hei yod hei`,
  '1#27': `h — yod hei hei vav hei alef dalet nun yod; and afterward before parshat Kadesh one should intend the simple alef and the name 72 and the name 161, thus: yod hei vav-yod hei alef hei yod hei vav hei; and afterward in each line one should intend the simple alef and one letter from the name 72 and one letter from the name 161, thus:`,
  '1#28': `{y. yod alef — this parshah has ten yods corresponding to ten sefirot and to the ten simple of Havayah} Vayedaber Hashem — intend that this Havayah corresponds to the alef of the name Eheyeh: "El Moshe lemor: Kadesh li kol bechor," etc.; "Vayomer Moshe el ha'am zachor" — intend that this Name is part one of the five of Eheyeh "imachem."`,
  '1#29': `{y. hei. hei.} Mizeh velo yo'chal chametz; hayom attem yotz'im bachodesh ha'aviv; vehayah ki yeviacha Hashem — intend part two of the five of Eheyeh "el eretz haKena'ani," etc.`,
  '1#30': `{y. vav. yod.} Bachodesh hazeh; shiv'at yamim matzot; chag laHashem — intend part three of Eheyeh; matzot to'chelu, etc.; vehigadta levincha — intend part four of Eheyeh "li."`,
  '1#31': `{y. hei. hei.} Betzeiti miMitzrayim; vehayah lecha le'ot — intend part five of the five of Eheyeh "beficha"; ki beyad chazakah hotzi'acha Hashem — intend part one of the yods of Eheyeh "miMitzrayim"; ushmartem et hachukah hazot.`,
  '1#32': `In general for parshat Vehayah ki yeviacha — intend the first heh of simple Havayah and the name 63 and the name 143, thus: heh yod hei vav hei alef hei yod hei; and afterward in each line intend the first heh of Havayah and one letter from the name 63 and one letter from the name 143, thus:`,
  '1#33': `{h. yod. alef. — this parshah has six verses corresponding to the heh of alef} Vehayah ki yeviacha Hashem — part two of the yods of Eheyeh; {b} veha'avarta kol peter; {g} laHashem — part three of the yods; {d} vechol peter sheger; {d} laHashem — part four.`,
  '1#34': `{h. hei. hei.} {g} vechol peter chamor tifdeh; {d} vehayah ki yish'alecha vincha machar lemor mah.`,
  '1#35': `{h. vav. yod.} Zot ve'amarta elav bechozek yad hotzi'anu; {h} Hashem — part five of the yods; {h} vayhi ki hikshah Par'oh; {v} vayaharog; {v} Hashem — part six; {z} zavach.`,
  '1#36': `{h. hei. hei.} Peter rechem hazcharim; {v} vehayah le'ot; {ch} Hashem — part eight miMitzrayim.`,
  '1#37': `In general for parshat Shema — intend the vav of simple Havayah and the name 45 and the name 151, thus: vav yod hei alef vav hei alef hei yod hei; and afterward in each line intend the six of simple Havayah and one letter from the name 45 and one from 151, thus.`,
  '1#38': `{v. yod. alef.} Shema Yisrael; {t} Hashem — part nine of the yods; {y} Hashem — part ten; {b} ve'ahavta; {a} Hashem — part one of the final five of Eheyeh.`,
  '1#39': `{This parshah has six verses corresponding to the six simple; and further intend to draw the seven havayot of Kadesh to the three havayot of this parshah in the secret of Chochmah and chasadim.}`,
  '1#40': `Nafshecha uvechol me'odecha; {g} vehayu hadevarim ha'eleh; {d} veshenantam.`,
  '1#41': `{v. vav. yod.} Levincha vedibarta bam; ushchartem.`,
  '1#42': `Le'ot al yadecha vehayu letotafot bein einecha; uche'tavtam.`,
  '1#43': `In general for parshat Vehayah im shamoa — intend the final heh of simple Havayah and the name 52 and the full name Adonai, thus.`,
  '1#44': `Heh yod hei hei vav hei alef dalet nun yod; and afterward in each line intend the final heh of Havayah and one letter from 52 and one from Adonai, thus.`,
  '1#45': `{h. yod. alef. — this parshah has seven verses hinting Malchut receiving from ChBaG TaNTZ; and further intend to draw the seven havayot of Vehayah ki yeviacha to the four havayot here in the secret of Binah and gevurot} {a} Vehayah im shamoa tishme'u; {b} le'ahavah et — part two of the final five of Eheyeh; {b} netati geshem artzechem.`,
  '1#46': `{h. hei. dalet.} {g} venatati esev; {d} hishameru lechem; {h} vecharah af.`,
  '1#47': `{h. vav. nun.} {g} Hashem — part three of the final five; {d} ve'avadtem; {h} asher.`,
  '1#48': `{h. hei. yod.} Beshevtecha; {ch} ulemadtem; {t} lema'an yirbu yemeichem.`,
  '1#49': `Order of Rabbenu Tam`,
  '1#50': `One should intend that in these four parshiyot there are twenty-one verses corresponding to the name El from Eheyeh with yods — alef-yod-yod-yod; and also El from Eheyeh in chesed as above; and that in these four parshiyot there are twenty-one mentions corresponding to Eheyeh as above.`,
  '1#51': `And afterward intend the simple Havayah including these four parshiyot and the four names issuing from the four letters of Havayah — 63, 45, 52, and full Adonai, and also El 161, 143, 151, thus:`,
  '1#52': `YHVH`,
  '1#53': `y yod hei vav hei h yod hei alef vav hei v yod hei hei h alef hei yod hei alef hei yod hei alef hei yod hei`,
  '1#54': `And before Kadesh intend the simple yod of Havayah and the name 63 and 161 and the combination of 161 and 63: y yod hei vav hei alef hei yod hei combined alef-yod heh yod vav hei hei`,
  '1#55': `And in each line intend the 42 letters of 72 and the simple yod of Havayah and six letters from the 42 of 72 and three from the combination of 161 and 63, joining at the start the simple yod of Havayah as diagrammed.`,
  '1#56': `This parshah has ten verses corresponding to ten sefirot and to the ten of simple Havayah`,
  '1#57': `{YHVH yod hei vav-yod hei yod vav dalet hei yod vav yod vav hei yod y YHVH yod yod alef} {a} Vayedaber {a} Hashem — part alef of Eheyeh; {b} Kadesh; {g} Vayomer zachor.`,
  '1#58': `{YHVH...} Et hayom hazeh... bechozek yad hotzi {a} Hashem part one of the first five of Eheyeh; mizeh velo yo'chal; {d} hayom attem yotz'im.`,
  '1#59': `{YHVH...} Bachodesh ha'aviv; {h} vehayah ki yeviacha {b} Hashem part two of the first five; eretz haKena'ani, etc.`,
  '1#60': `{YHVH...} Eretz zavat chalav udevash; {v} shiv'at yamim; {z} chag {g} laHashem part three.`,
  '1#61': `{YHVH...} Matzot to'chelu; {ch} vehigadta; {t} laHashem.`,
  '1#62': `{YHVH...} Li betzeiti; {t} le'ot; {h} torat {h} Hashem part five; ki beyad chazakah; {d} ushmartem.`,
  '1#63': `{YHVH...} Mimitzrayim; ushmartem hachukah.`,
  '1#64': `{h yod hei alef vav hei alef hei yod hei combined alef-yod hei alef yod vav hei hei} Before Vehayah intend first heh of Havayah and name 45 and 143 and combination of 143 and 45; in each line intend 42 of 63, first heh, six from 42 of 63, three from combination 143-45, joining first heh as diagrammed.`,
  '1#65': `{YHVH yod hei vav hei...} {six verses} Vehayah ki yeviacha {b} Hashem; veha'avarta kol peter.`,
  '1#66': `{YHVH...} Rechem {g} laHashem; {d} vechol peter; {g} vechol peter chamor.`,
  '1#67': `{YHVH...} Ve'im lo tifdeh; vehayah ki yish'alecha.`,
  '1#68': `{YHVH...} Zot ve'amarta bechozek yad; {h} Hashem part five; {h} vayhi ki hikshah.`,
  '1#69': `{YHVH...} Leshalchanu vayaharog {v} Hashem part six kol bechor.`,
  '1#70': `{YHVH...} {z} laHashem part seven kol peter; {v} vehayah le'ot.`,
  '1#71': `{YHVH...} Bein eineichem {ch} Hashem part eight miMitzrayim.`,
  '1#72': `{vav yod hei hei vav hei alef hei yod hei combined alef-yod hei hei yod vav hei hei} Before Shema intend six simple of Havayah and name 52 and 151 and combination 151-52; in each line intend 42 of 45, six simple, six from 42 of 45, three from combination 151-52, joining six of Havayah as diagrammed.`,
  '1#73': `{YHVH yod hei alef vav hei...} {seven verses; draw seven havayot of Kadesh to three here in Chochmah-chasadim} Shema {t} Hashem; {y} Hashem; ve'ahavta.`,
  '1#74': `{YHVH...} Et {a} Hashem part one of final five; bechol levavecha.`,
  '1#75': `{YHVH...} Uvechol me'odecha; {g} vehayu hadevarim.`,
  '1#76': `{YHVH...} Hayom al levavecha; {d} veshenantam levincha.`,
  '1#77': `{YHVH...} Beveitecha uvelechtecha.`,
  '1#78': `{YHVH...} Le'ot al yadecha; letotafot.`,
  '1#79': `{YHVH...} Al mezuzot beitecha.`,
  '1#80': `{h alef dalet nun yod} Before Vehayah im shamoa intend final heh of Havayah and full Adonai; in each line intend 63, 161, 45, Adonai, final heh, six from 63-161-45-Adonai, two from full Adonai, joining final heh as diagrammed.`,
  '1#81': `{yod hei vav hei alef hei yod hei yod hei alef vav hei alef dalet nun yod h yod hei vav hei} {nine verses — Malchut from ChBaG TaNTZ; draw six havayot of Vehayah ki yeviacha to four here in Binah-gevurot} Vehayah im shamoa; {b} le'ahavah et {b} Hashem; venatati geshem.`,
  '1#82': `{yod hei vav hei...} Uvechol nafshechem; {b} venatati matar; {g} venatati esev.`,
  '1#83': `{yod hei vav hei...} Ve'achaltem; {d} hishameru; {h} vecharah af.`,
  '1#84': `{yod hei vav hei...} {g} Hashem part three; ve'atzar et hashamayim.`,
  '1#85': `{yod hei vav hei...} {d} Hashem part four; {v} ushmartem; {z} ulemadtem.`,
  '1#86': `{yod hei vav hei...} Bein eineichem; {ch} uche'tavtam.`,
  '1#87': `{yod hei vav hei...} Beitecha; {t} lema'an yirbu yemeichem {h} Hashem part five la'avoteichem.`,
  '1#88': `And examine well in Sha'ar HaKavanot drush ha-tefillin and in Shemen Sasson what the Rashash z"l wrote there on the order of writing tefillin; and you will understand all the order of kavanah we wrote — only that we wrote them in more detail and each line-kavanah in its place to ease the scribe who intends, so he not become confused, as I found arranged in the manuscript of our friend the divine kabbalist R' Shaul Chaim Dweck haKohen, may his light shine, author of Eiphah Sheleimah on Otzar HaChaim — end.`,
  '1#89': `And know: although it is written there in the Rashash that before parshat Vehayah im shamoa one says three times the filling of Adonai — one need not intend except once, since afterward in the kavanah of the lines the Rav wrote to intend only once; likewise before the parshah one intends only once.`,
  '1#90': `And further know: what is written in Sha'ar HaKavanot that in the yod of the filling of the filling of the name 63 the vav is filled with alef — this is an error; it must be filled with yod, as the Rashash z"l wrote in the siddur in all kavanot of fillings of the name 63 — the vav of the yod is filled with yod — see there.`,
  '1#91': `And one must know one introduction: do not think, God forbid, that above there is any letter or vowel-point; rather all is to ease the ear of people dwelling in this material world who cannot know supernal lights — therefore they depicted names and letters; but the truth is every name, letter, and point hints at supernal lights that we cannot know their essence, and each hints at a particular light — as Maharach z"l expanded in his introduction to Sha'ar HaHakdamot — see there.`,
  '1#92': `And afterward one crowns with the tagin SHaTNaZ GaTZ and with the vowels TIPH, and intends the kavanah of the tagin written with us in siman 36 ot 15.`,
  '1#93': `And one makes the houses, straps, knot, and stitching according to the kavanot we wrote in siman 32 ot 175 — see there.`,
  '1#94': `And know there is no difference between tefillin of Rashi and of Rabbenu Tam except regarding the Havayah: according to Rashi it is 72; according to Rabbenu Tam it is in the secret of Y-H-H-V havayot one within another; but in all other details there is no difference — Sha'ar HaKavanot drush 10; and so Mishnat Chassidim, tikun tefillin chapter 15 ot 1: "Afterward one writes tefillin of Rabbenu Tam in all the details written for those of Rashi," etc. — see there; and so the order of Sha'ar HaKavanot for tefillin of Rabbeinu Tam.`,
});

patchFile('siman_035/mateh-yehonatan/part-001.txt', 'mateh-yehonatan', {
  '1#_': `(Siman 35 seif 2) All this is called exchange and treifah. Shach s.k. 5 and Maharshal Piskei Tosafot siman 37 permits all these exchanges, etc.; and Mahariu and Mahar"a of Prague wrote this is called exchange. It must be that these treifos are mentioned in the Gemara that says "missing or extra" — meaning: if missing or in a bed (arugah), then also called missing or extra, not like R' Meir who wrote missing or extra means in any two beds, as Shach wrote s.k. 3 there; if so, one should not explain exchange as three on the left and two on the right — rather exchange means in form, as Rama wrote.`,
  '2#_': `(There) The varda if missing, if it has, etc. Taz s.k. 4. According to the Mechaber's view one should not challenge that which they said in chapter Eizehu Mekoman daf 47a: this "between and between" that comes before Rav Ashi — R' Eliezer would declare them treifah; R' Huna bar Rav said to him: all these animals of the baraita have it, etc. — one may say it is relevant because their animals did not have ayinunita de-varda, yet they live; or extra from the front is kosher — therefore it had to say all these animals of the baraita, etc. But according to Rama who holds missing varda is treifah — then necessarily this "between and between" deals with two vardot, as Tosafot wrote s.v. kol hani, etc., there; and if two are found, nevertheless they declare treifah — it is difficult, for all these animals of the baraita have two vardot; and it must be that it deals when there was only one; and that which it did not say extra from the front is kosher — to teach us that if two are found it is treifah, that we do not judge it as extra from the front but as extra varda; and we learn that if it has no varda at all, or two are found — treifah.`,
});

patchFile('siman_035/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The laws of treifos of the lung and its lobes (onot). In it are 10 seifim. If the lung was perforated — treifah.`,
  '2#main': `Five lobes (meaning: like ears) the lung has — three on the right and two on the left — when the animal is hung by its legs and its intestines face the slaughterer, for then the animal's right and the slaughterer's right are one; and it has additionally on the right side one small lobe called ayinunita de-varda, and it does not stand in the order of the lobes but is distant from them toward the face; and if one is missing from the right, or from the left, or there were two on the right and three on the left — treifah. {Rama: The forms of the lobes of the right are not like those of the left, and if their form was exchanged — treifah; and likewise when the middle lobe of the right is larger than the lower one — treifah (Mahariu); and if the lobe of the left upper one is larger than the upper lobe of the right — treifah; and likewise if the ama of the right is larger than that of the left — all this is called exchange (chalif) and treifah (Mahar"a of Prague).} And the varda: if it is missing, or if it has two, or if it is found on the left side — kosher. {Rama: And in these lands they practice to declare treifah both when two vardot are found, or if it is missing, or if it changed its place (Mahariu and Or Zaru'a) — and such is customary, for many authorities hold thus and one should not change the custom; and likewise if it changed its accustomed designation and form — treifah (Igur); if two vardot are found in it and they have one root like the thickness of a finger, even though there is a crack in it — kosher (Magid Commentary in Badei Yeshayim) (Or Zaru'a in the name of Ravyah and so Mahariu, and it is in Hagahot Ashiri); and if one is inverted and the other is not inverted — we follow the larger one, and if it is not inverted — kosher (ancient examinations). The varda's way is to be in a pouch; and if no pouch is found for it, or it has two pouches, or it has a pouch and is not placed in it — and even when they place it inside it comes back out when the lung is inflated — treifah (Kol Bo in the name of Rabbenu Moshe bar Yehudah and hagahot of Mahariu and ancient examinations and somewhat from oral tradition — actual practice in Wirmisha in the name of Maharash of Ziria). And all these laws are only in places that practice to declare treifah for two vardot or no varda at all; but in places that permit, all these exchanges are kosher (Beit Yosef). If part of the varda is missing, one should examine the lobes or the ama on the left side (some texts: on the right side); if the missing piece is found — some say kosher, for thus is sometimes found in kids and lambs (so found written); and some permit if it has rose-form at its root like finger-thickness even though it has no rose-form on its head, only that it not be inverted and not have changed its place; and all these matters may be treated leniently since many permit in every regard.}`,
  '3#main': `If lobes were added in their count — if the extra lobe was at the side of the lobes or before the lung, which is opposite the heart — permitted; and if it was on its back, which is opposite the ribs — this is treifah; and this is when it is like a myrtle leaf after they inflated it; but if it is less than this — kosher. {Rama: And some are stringent to forbid any extra lobe that is not in the row of lobes (Hagahot Ashiri and Mordechai and Semak and Mahariu and Tur in the name of Ittur and Or Zaru'a); and so they practice in some places to forbid an extra lobe even from the front (mikama), and they do not distinguish between front and back except if it stands in the row of lobes; and when they inflate it, if it leans forward — kosher; and if it leans toward the back — treifah (Mahariu and Beit Yosef in the name of Magid Commentary); and in these countries the custom is to permit an extra lobe from the front, and one should not change the custom.}`,
  '4#main': `If an extra lobe is found at the end of the slopes of the ama — kosher (for this is called in the row of lobes) (Beit Yosef).`,
  '5#main': `The right lobe adjacent to the gullet in the narrow of the chest at the neck — the lower one that is upper adjacent to the neck — if on its back is found like a myrtle leaf (tarfa de-asa) — kosher, because such is its way to split; and specifically the right one, but not the left; and some say: specifically above half of it, but below half — treifah. {Rama: That which we permit an extra lobe in the row of lobes — nevertheless we require that there not be more lobes on the left than on the right, such as four on the left and three on the right (Mahariu); but if they are equal on each side — three or four lobes on each side, and all stand in the row of lobes — kosher (there in hagahah); and if in one lobe something like a crack is seen, it combines to permit, but not to declare treifah, for we are not concerned about cracks to declare treifah (so found written); a lobe that split and has one root like finger-thickness is not counted except as one (Mahari Mulen); and it is not called an extra lobe unless it has the form of a lobe; but if on the lung's surface a place is found high, wide below and thick above, not sharp at its head — it is called a lump (gavshushit) and kosher (Mahariu and Beit Yosef in the name of Magid Commentary); and likewise if a lobe is found on the lung's surface and a hollow beneath it, and when they inflate the lung all the lobes fall into the hollow and are level with the rest of the lung (Rabbenu Yaakov Weil and Beit Yosef) — even though it does not enter the hollow except when one places the hand gently on it — kosher, for this is not an extra lobe but a splitting of the lung; and since it has a hollow beneath to rest in, it will not come apart like other extra lobes — kosher (some say); and one may not permit such a split except from the back, where the split rests on the hollow; but from the front the split falls downward and will eventually come apart — treifah (so found written); some say: if an extra lobe is found opposite the groove of the varda — its law is like a split with a hollow (Mahari Mulen in the name of R' Meir the slaughterer); and one should not rely on this except in a time of distress and great loss.}`,
  '6#main': `One of the lobes that is less than a myrtle leaf after inflation — it is considered missing and treifah.`,
  '7#main': `If one is missing from the right lobes, the varda completes it (and some say it does not complete) (Rashi and Tosafot and Rosh) (and such is customary).`,
  '8#main': `A lung that does not have the cut of a lobe — treifah; and if there is a crack like the appearance of a separation between them, of the measure of a myrtle leaf — whether at their root, whether in their middle, whether at their end — kosher. {Rama: And some permit with a sign or a crack of any size, even though it is not like a myrtle leaf (Rashi and Ittur and Tosafot and Semag and Rosh and Tur and Rabbeinu Yerucham and Tashbetz and Mordechai in the name of HaG and R' Chaim and Rashba and Ravyah); and one may rely on them if there is great loss to declare treifah (should read: to permit). The lower lobe of the right — its way is to be thick and long more than the middle lobe; also it is higher than that of the left; and if it is completely attached to the ama, only a sign of these signs is seen in the place where a lobe should be — it is called a sign and kosher (Mahariu); and the same if another sign is recognized there by which the lobe is somewhat recognized; and even a sign through the usual furrow (simpun) of a lobe — if a furrow is found in the usual place of a lobe, it is called a sign (Magid Commentary in the name of Maharik); and all these matters we examine and estimate after they inflated the lung, because in the animal's lifetime the lung is inflated. Some say: in kids and lambs we do not declare treifah if lobes are not found, even without any sign or crack at all, for such is their growth and their way — in their youth they do not have them, and when they grow the lobes grow with them (ancient examinations of Maharash).}`,
  '9#main': `If on one side of the lung one lobe is missing, but at the end of the ama on that side there was a large protrusion like a lobe — even though the way of lobes is to be adjacent to one another and here the ama interrupts between them — kosher. {Rama: And some practice to declare treifah in such a case, because all that is below the varda is called not in the row of lobes; and so they practice in these countries.}`,
  '10#main': `All these matters are stated only regarding behemah and chayah; but a bird does not have lobe-cutting like an animal, and if found — it has no known count.`,
});

patchFile('siman_035/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `(Siman 35, Taz s.k. 2) And R' Shlomo wrote, etc. See in Shach s.k. 9 that this is not R' Shlomo's view; and what appears for practical law.`,
  '2#_': `(There s.k. 6) His wording is garbled. See in R' Shlomo that it is corrected and I brought it in my book; and in Shach I abbreviated according to what appears for practical law to be lenient in every case — examine.`,
  '3#_': `(Taz s.k. 10) And it appears Rama also agrees in this, etc. This is not so, for he did not rule thus explicitly in Darkei Moshe; and this is his wording in my book; and he wrote in Hagahot Ashiri, etc.; and Beit Yosef wrote: and it is a simple matter that there is no aspect of prohibition here; and so Darkei Moshe, that so appears from his words in the hagahah; and so the R"tz; and so they practice in Krakow; and so is the essential law, unlike Maharshal Piskei Tosafot siman 33 and Bach who forbid here — end.`,
  '4#_': `(Taz s.k. 12) That if it was shorter than the hollow, etc. This is not so — ultimately, since it rests in the hollow it will not come apart; and perhaps there is a printing error in his wording — it should read: if it was longer than the hollow, and he holds treifah because it presses on the ribs, as Shach wrote in small seif 36 in the name of Darkei Moshe — that is the reason for a split that has a hollow beneath: it does not press on the ribs; but his wording that concludes "then it is not a split" does not seem to mean this.`,
  '5#_': `It appears: if on one side, etc. And in Shach I wrote thus in the name of Maharam — see there.`,
});

patchFile('siman_035/peleti/part-001.txt', 'peleti', {
  '2#א': `All this is called exchange and treifah — the acharonim, headed by Maharshal, disagree to permit them, for they have no root in the Gemara; and in truth these can be imagined that the early ones erred in this, and certainly there is room to permit; but it is far-fetched to believe they considered there is a root in the Gemara, for if this exchange were the Gemara's intent, the Gemara should have said first: form and shape of the ona and its place, and afterward say exchange is treifah; but since it did not mention this at all, how can exchange and treifah apply to these exchanges that never appeared in the Gemara? And great is the heart of decisors — Mahariu brought in his responsum, and it is clear it was a received tradition in his hand from ancients, for Torah was transmitted to the sages of Ashkenaz and the valley; they found and fenced and established and accepted to act according to the slaughter of Mahariu — if so, how can one abolish it? Granted, if we could attribute it to error that he thought the Gemara meant thus and erred in understanding — it would be mistaken custom; but this does not enter my mind that such great ones of the generation, from whom Torah literally went out in Ashkenaz and its branches, would err in such simple matters; this is only tradition in their hand from ancients, and they accepted to act thus; if so, it is a complete prohibition to change this custom, since it is not error; and who knows — perhaps they knew many matters in tradition that were not mentioned in Chazal's words, like meat that remained three days without salting, and the like; God forbid to change; therefore many rely on Maharshal and are very lenient — God forbid to be lenient, for behold this breaches the fence of what we received from our fathers, who had tradition to forbid such exchanges — God forbid to say they erred in a simple matter; and do not forsake your mother's teaching.`,
  '2#ב': `If two vardot are found — Taz in s.k. 4 challenged: below we ruled extra from the front is kosher — why declare treifah for two vardot? Answer: we do not forbid on account of extra, only since it should have varda designation, all extra is considered as removed and missing varda is treifah — end. And still difficult: for the Gemara says this "between and between" that came, etc. — he thought to declare treifah; he said: all these animals of the baraita have it and call them ayinunita de-varda; and Rashi explained one existed, and from this he explained if missing — kosher, for it was thought to declare treifah as stated; but Rabbenu Ephraim explained one, and certainly only the name was two; nevertheless he permitted. If so, difficult with two vardot found — how do we explain in the Gemara "all these animals of the baraita," etc.? If the explanation is like Rashi that it was only one ayinunita de-varda — if so, Rashi and Tosafot raised that missing varda is kosher; if so, with two vardot found it should also be kosher, for we cannot declare treifah because of extra, for missing varda is kosher; and if they explain like Rabbenu Ephraim with two vardot — the case was obvious it is kosher, for he permitted explicitly because "all these animals of the baraita"; and it is strained to say for us "all these animals of the baraita" does not apply, for it is not common in reality — this is against the poskim's implication; it must be explained like Rashi; nevertheless even according to that explanation missing varda is kosher, nevertheless with two it is treifah, for Ramban holds all extra is considered as removed and it is a perforation in that place; and even here, as considered removed varda, it is as if the lung was perforated; and so Shulchan Aruch below regarding liver: according to Ramban if two livers adhere to the mesentery — treifah, even though removed liver is kosher, nevertheless this is as perforated in the mesentery; and so one may say here. And one may resolve: except I did not know whether Tosafot decided if according to R' Eliezer the case was with two ayinunitot, and from this they decided that missing varda is treifah — whence do we know, since he does not permit extra from the front, one may say therefore he thought to declare treifah because it is extra; but not because removed varda is considered — what of it if varda is missing, since it is not received that there must be varda, only the prohibition is extra not in the row of onot; whence do we add treifos? Rava said five onot and above said or missing and extra treifah, and did not mention varda at all; also somewhat proves it does not refer to missing, for "extra" does not refer to it, and none mention varda; if so, whence did the ruling come to forbid? And there is room to resolve: and behold it is astonishing in Rambam who ruled missing varda or two is kosher and extra from the front also kosher — if so, what reason and for what purpose did he tell him "all these animals of the baraita have it" from Scripture to declare treifah? If because of varda — in every case kosher; if because of extra — extra from the front is kosher. It must be said Rambam holds that permitting all extra from the front is because we see all these animals have it — we learn the count of five onot is not fixed, for varda is also counted as extra ona; and we saw it has one and two; even all extra from the front is kosher; unlike if not for "animals of the baraita have it," extra from the front would be treifah — examine.`,
  '5#א': `Nevertheless we require that there not be more onot on the left than on the right; and Pri Chadash challenged s.k. 94: since there are three on the right, what difference if on the left more? — and he concluded from Rambam — see there; and even though my view tends thus, for the Gemara said exchange treifah — meaning missing so only two on the right and three on the left; if all is exchange, even three right and four left — cannot be Rava's intent; Rava holds extra even in the row is treifah; if so this does not exist; if extra exists — treifah; Rava did not intend this; we hold not like Rava to permit extra, yet we cannot innovate treifos in exchange; in great loss one may be lenient on Rambam — Pri Chadash.`,
  '5#ב': `But split from the front falls downward and will come apart; and Shach and Pri Chadash wrote: even for those who permit extra from the front, this is different, for the split is from the body of the lung, and when they inflate the lung the split falls downward and it appears it split from the body of the lung and will come apart and is treifah. And one should not challenge: since the reason is that it split from the body of the lung — then why did the Gemara labor siman 47b to find an explanation for "lung perforated or missing" — let us say in such a case it is missing from the body of the lung and split and it is from the front and treifah, and this is what it teaches that in such a case treifah because it will come apart; and if so, perforation and missing are counted as one, for in conclusion we establish it needs only R' Shimon — also missing means perforated. And see below siman 36 where you will find all these difficulties resolved together; and it appears since this treifah is not because of extra but because it will come apart, even less than tarfa de-asa is treifah because it will come apart; and to say if not so large the lung will not come apart — this is strained, and whence do we be lenient on a Torah prohibition? — unlike Maharatz in hagahot of slaughter who is lenient in this.`,
  '8#א': `Crack — and they raised that we say regarding cracks to permit and not to declare treifah, even in one place, as Shach wrote; meaning we are lenient because since most of the lung is not missing we find; therefore all we can say they are not included in missing, we say; if so, it appears the same law applies to an upper ona that split — the splits complete the count of onot, for even though we are lenient that there should not be extras, nevertheless here there is a count of an ona to complete; and this is simple, better than cracks.`,
  '8#ב': `And there are those who permit, etc. — and Maharshal agreed with Rambam; and in truth the Gemara can be understood: we say it resembles sponge — treifah — why is this needed? Behold onot are missing, and explicitly they said missing from five onot is treifah, and here all are missing; and from Maharshal's words it appears he holds when entirely attached one may more permit, for there is no order they should be missing; but for one or two missing it is worse — this is strained; and Shach wrote like Ran: where there is any sign we say they stuck to each other; and this does not help for that which says it resembles sponge — either way: if there is a sign it is truly kosher; if no sign — explain it is missing; and from Shach it appears because of missing any sign helps, unlike for "resembles sponge" where we require crack sign. And in my heart I say: each ona is surrounded by the lung's membrane, and inside is placed like lung flesh; if two onot appear as one, we check if that portion was cut and we find for each a separate membrane — behold it is clear there were two onot, for there are two membranes; if they stuck strongly, it is known that in their adhesion two membranes will be found pressed together — this is a sign there were two onot that only stuck; and there is no invalidity because of missing, for there were two membranes; invalidity is only resembling sponge; through this crack and the like help; but if the onot were cut and there is only one membrane — it is proven it is only one ona and the count is missing and treifah; crack and simpun do not help, for behold suspicious matter is before you — examine. Nevertheless for the law he was stringent and did not rely on crack and simpun if cut and only one membrane remains; and it is strained to be lenient that they stuck so strongly one cannot distinguish one or two membranes — this is difficult in reality that there would be four membranes, for otherwise each ona has two membranes that would be four stuck together and not felt; therefore one should be stringent; and if the membrane is recognizable — obviously there is no missing, only because of resembling sponge; if so, all the above difficulties are resolved — examine.`,
  '10#_': `And if found — it has no known count; and that which the Gemara Chullin 56 did not answer when Chizkiyah said a bird has no lung and the Gemara challenged "but we see it has" and the Gemara answered "not to fall and not to be crushed" and did not answer simply "for the count of the lung" regarding missing count and extra and exchange that have no known count — it is strained to say it chose those two treifos mentioned in the Mishnah, unlike missing and extra which are only statements; and it appears to say: there R' Yehudah and Shmuel dispute regarding a bird whose body slipped whether treifah or needs examination lest the lung was perforated; Chizkiyah said a bird has no lung — behold we need not be concerned for lung perforations that you require examination; if so, how does "not to fall and not to be crushed" relate to the concern lest the lung was perforated? It may be said thus was his intent in "fell from the roof": we are not concerned to examine the lung, nor concerned lest the small bones connected to it for the lung were broken or crushed and perforated; and we do not establish suspicious matter in the lung; if so, the same for slipped body — we do not establish suspicious matter in the lung; and they disputed whether there is more suspicious matter in slipped body than fallen; if so, one may resolve: his intent was not on missing and extra; for what does this matter to slipped body? The statement of Chizkiyah refers to the matter above.`,
});

patchFile('siman_035/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `That it changed its place. Baer Heitev; and see in Sefer Be'er Yaakov he raised regarding a case of inverted groove found in Jewish cattle, and there is great financial loss — one may permit even the animal, and all the more the milk; his colleagues agreed — see there; and see from this in responsum Zichron Yosef Yoreh De'ah part 2 siman 2 and siman 3 at length. [And what Baer Heitev wrote s.k. 4 in the name of responsum Noda Biyehudah: minor loss is, etc. — see there siman 31 s.k. 2 from this.]`,
  '2#_': `And if no pouch was found for it. See in responsum Arba'ah Turim Even siman 19: if the pouch was perforated with a through-hole — all agree it is kosher; his father the Gaon R' Elazar Rokeach agreed — see there.`,
  '3#_': `Pouch. Baer Heitev of the Rav Maharit translated in the name of Shach that in great financial loss one may be lenient; and it appears he understood from Shach's words at the end of s.k. 14 that "in great financial loss one may permit" refers also to the beginning of his words regarding missing pouch or not placed in pouch; and in my opinion it appears from Shach's arrangement that it refers only to extra pouch; but regarding those one may not permit even in great financial loss; and so Peri Megadim explained. And see in responsum Pri Tevuah siman 62 that he is in doubt how to interpret Shach's words, and he straddles both sides; and he raised for practical law: if the animal was slaughtered twelve months ago, one may permit in great financial loss even the animals themselves, and all the more cheeses made from them — see there.`,
  '4#_': `Kosher. See in responsum Shav Yaakov part 2 end siman 60: one may not be lenient except in a time of distress or great financial loss — see there; and see in responsum Beit Efrayim Choshen Mishpat siman 13 and 14 on this matter many novel laws at length.`,
  '5#_': `Even though it has no varda designation. [See in responsum Chavot Yair siman 32 explained there that Rama here deals even if at its head it is sharp like the form of an ona — see there.]`,
  '6#_': `Toward the back — treifah. [Baer Heitev: what he wrote "and specifically protruding," etc.; and see in Shulchan Melachim seif 13: it appears from his words that bending leaning like tarfa de-asa measure he calls protruding and treifah; and what is less than that he calls slight bending and kosher — see there; and they also brought in Pri Megadim; and see in Torat Chesed siman 40 who elaborated on this, and his view is to rule that for bending we have no concern even like tarfa de-asa, only for actual protrusion treifah if it is like tarfa de-asa. And the definition: what is called protrusion or bending. It appears: whatever is rooted properly in one row with the onot and only above in its height and tip leans toward the back is called bending and permitted even more than tarfa de-asa, as explained there is no distinction between tarfa de-asa and more; however if at its root place it thickens and protrudes also outside its place, and on the contrary above it goes straight and does not bend but below at its root protrudes outward — this is protrusion and treifah if the protrusion is like tarfa de-asa; unlike an ona that is not extra, which is kosher even in such a case — see there he elaborated to bring proofs for this explanation, and such is primary for practical law; only one who is stringent for himself — examine.]`,
  '7#_': `Because its way is to split. See in responsum Givat Shaul siman 56: a case came before him where on this ona exactly on its tip on the side toward the windpipe there was a small protrusion less than tarfa de-asa, and it was exactly equal to the ona that rose in inflation equally, only adhesion emerged from that protrusion to the chest fat, and the adhesion passed through compression — and he permitted; and he wrote one should not forbid because of two suspicious matters, for since its way is to split it is not called suspicious matter at all — see there further.`,
  '8#_': `That specifically above half. See in responsum Or Zaru'a Panim Me'irot part 2 siman 157 who raised: in the half and above one may permit whether from the front or from the back; but from half downward: if from the back — treifah; but from the front one may permit — contrary to the slaughter examinations of Maharatz who wrote that even from half and above that is kosher refers specifically from the back, but from the front some declare treifah because it will come apart; and so in slaughter examinations of Gevul Binyamin — but this is error and one need not be concerned; and he wrote this is not among permitted matters, etc., for slaughterers learn slaughter and suppose as if given from Sinai, etc.; and he wrote the sages of the city agreed with him to permit extra from the front, since many animals were found thus and there is great financial loss — see there; and see Pri Megadim. [And see in responsum Chavot Yair siman 38 who wrote on this: if it is literally extra from the front — the Bach forbids s.k. 20; and if it stands exactly on the tip and through inflation the root appears to lean from the front — at first glance treifah like other onot whose extra leans toward the back — the same here toward the front; and specifically when the root leans, not merely the tip; however expert examiners here told me: even if the root leaned forward on the upper ona, this must be distinguished while the lung is still inside the animal, for there it is pressed in the narrowness of the chest in its lifetime, and when they remove it it expands and therefore sometimes the root leans forward — therefore one must distinguish this while still in the animal in the place that presses it — and these are matters of reason — end.]`,
  '9#_': `To declare treifah. Baer Heitev: however Taz wrote, etc.; and see in Dagul Mervavah who wrote that even Maharshal and Taz forbade only when the crack also combines yet there is equal on each side right and left; but if on the right there were two onot and two cracks, even though on the left there were three onot literally — nevertheless since through the cracks there are more on the right than on the left, even according to Maharshal and Taz it is kosher — see there.`,
  '10#_': `Only a split. See in responsum Me'ir Netivim siman 41.`,
});

patchFile('siman_035/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  '1#_': `Lung perforated. And see in my Sefer Beit Efrayim siman 20 that I wrote to clarify the words of Or Zaru'a in Teshuvot siman 35: all lung treifos are because of perforation for us only according to Rambam, who holds missing is a category by itself; and his proofs are clear and lucid like a new word.`,
  '2#_': `Or if it changed its place. Baer Heitev wrote in Zichron Yosef siman 2 regarding a cow that calved twins or bore twins and afterward was slaughtered and ayinunita was found inverted — the groove was opposite the heart; the law of cheeses made from its milk — see there; and in my Sefer Beit Efrayim siman 35 I wrote on this.`,
  '3#_': `And it emerges when they inflate the lung — treifah. Baer Heitev; and see in responsum Pri Tevuah siman 73: cheeses made from an animal whose varda was found outside the pouch.`,
  '4#_': `Kids and lambs. Baer Heitev; and see in Shav Yaakov part 2 siman 60 on that which Shulchan Aruch seif 2 in the hagahah: if a piece is missing from the varda — kosher, for sometimes thus found in kids and lambs — they challenged him: certainly presumably in large animals too it is so, for it did not change; and he answered: it may be said when they grow the varda grew and became whole; and it may also be said certainly the shepherds' custom when they sense weakness they do not let them grow, etc.; and see Shach who doubts this leniency; and one may not be lenient except in distress and great financial loss; and see what he wrote there siman 65 regarding liver in calves; and see in my Sefer Beit Efrayim on this.`,
  '5#_': `If onot were added, etc. And see in Shav Yaakov part 3 siman 103: two protrusions on the lung from the front of the upper ona — kosher; see in my Sefer Beit Efrayim siman 35 — see there.`,
  '6#_': `Like tarfa de-asa — kosher. Baer Heitev; and see in Nekudot HaKesef siman 11 in the law of split on the upper ona in the middle of the groove with a hollow beneath it; and I brought in my Sefer Beit Efrayim siman 35 s.k. 140 — see there.`,
  '7#_': `But below half — treifah. Baer Heitev; and Pri Megadim wrote Choshen Mishpat part 2 siman 154: an ona of the right where extra was found below its half, etc. — see in my Sefer Beit Efrayim siman 35 s.k.`,
  '8#_': `It is called a lump and kosher. See Baer Heitev; and see in my responsum Beit Efrayim siman 26: split from the back with a hollow beneath it; and there is another suspicious matter there that combines to be two suspicious matters and treifah; and one may not permit except in onot that split in their width or thickness and have one root in a matter where there is no split there, only divided as I wrote in my book; and above siman 1; or extra on the upper ona in a place that is kosher because its way is to split and this is not included in suspicious matter at all; but split from within a hollow is certainly suspicious matter, not because of concern for extra but because of spoilage and change in the lung; therefore when another suspicious matter combines with it — treifah.`,
  '9#_': `And will eventually come apart and treifah. Baer Heitev; and see in my Beit Efrayim on lung treifos in the section of responsa siman 46: I brought at length in the name of my uncle the Gaon R' Sender; a lung where part shriveled and thereby became smaller than the middle — at first glance two suspicious matters; nevertheless one may be lenient in great financial loss, for in this case no distinction falls at all, etc. — see there "matter in reason." And in my responsum Beit Efrayim part 8 in manuscript I wrote: if it has a blister with suspicious matter of exchange, even in places that practiced leniency for blisters of siman 47 with another suspicious matter — one should declare treifah even in great financial loss; see there what he wrote for local customs that permit exchange in such a case in great financial loss — see there.`,
  '10#_': `It would be missing and treifah. Baer Heitev; and Me'ir Netivim siman 41 wrote: a lung that was divided in two, whether in length or width — one should not consider it a split, as long as the lung appears to the eye like the image of divided; and he again wrote there was extra pouch, and even though the varda does not touch this pouch — in this Rama permits; and even though it does not appear so from HaRav — nevertheless one may be lenient in great financial loss; except it may be said this part resembling divided is from the varda because somewhat it appears on that side the varda is not in the completeness of proper roundness, and there is room to doubt it was placed on the side of that extra pouch, for so it was when they inflated the lung those places adhere somewhat; and even though that part has no varda designation, nevertheless when there is a missing part of the varda and a separate extra pouch section, one should be stringent because of three suspicious matters, as explained in responsum siman 35 seif 36; nevertheless here, since even without combining the part there is a complete varda, there is no suspicious matter of missing, and also no suspicious matter of extra because that part has no varda designation at all — one may permit in great financial loss; and in that lung there was also permitted extra next to the split — there are not two suspicious matters adjacent, for healthy lung flesh separates them — this one alone and that one alone — end. And in my opinion it is not clear to say "resembles divided" if there is room to judge it as missing varda beneath — the wise one's eyes are in his head to distinguish between them; if it is this or that, there is no room to fall into doubt at all; and there where the piece in the place appears it has no connection to the name — if it is not relevant here, make it relevant to completing the varda; but when the eye sees it is a part from here, it does not appear to combine to the varda; and if there were no varda designation except the part — obviously we would not need to combine at all; and also in the substance of what he wrote: whatever appears to the eye as resembling divided is not considered a split — whence do we know this thing is divided and not split? And indeed regarding split versus divided, in my view it is explained well in my Beit Efrayim on treifos siman 35 and in my responsum Beit Efrayim Yoreh De'ah part. And see in responsum Pri Tevuah siman 40 regarding split from the front at the root — he wrote to forbid — and see there siman 70 and what I wrote on his words in my responsum Beit Efrayim; and there I clarified everything well with God's help.`,
});

patchFile('siman_035/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#_': `<b>A lung that was perforated, etc.</b> The main treifos of perforation of the lung will be explained below siman 36 — see there.`,
  '2#א': `["<b>And it is called ayinunita de-varda.</b> Like a small ona (lobe) of varda, on account of its delicacy and redness. Rashi:"]`,
  '2#ב': `["<b>Or from the left.</b> It implies that even if there are four on the right, if one is missing on the left — treifah; and so is implied from all the poskim; and so is also implied explicitly from the words of the poskim regarding completing the varda — see there; and it is simple in everyone's mouth, unlike the book Torat Chaim who permits in this:"]`,
  '2#ג': `["<b>Or if there were two on the right, etc.</b> And likewise also four on the left and three on the right is exchange (chalif) and treifah, as the Rabbenu wrote in seif 5:"]`,
  '2#ד': `["<b>All this is called exchange.</b> And Maharshal Piskei Tosafot siman 34 permits all these exchanges and does not declare treifah except for the exchange that the Tur mentioned, which is in the Talmud and poskim — and the exchange where the amot are above and the onot below that was mentioned in the words of the acharonim; and so Bach wrote to be lenient in great financial loss — see there:"]`,
  '2#ה': `["<b>Or if it has two.</b> Meaning: even if they do not stand one next to the other:"]`,
  '2#ו': `["<b>Or if it is missing, etc.</b> And Darkei Moshe wrote it is implied in Igur that if it is less than a myrtle leaf after inflation — treifah — end of his words; and it is explained thus in Igur that I brought in s.k. 9:"]`,
  '2#ז': `["<b>Or if it changed its place.</b> For its way is to stand below the onot and it has a groove; and when they inflate the lung the groove is aligned opposite the cut between a lobe and the ama, and its back opposite the heart and its face opposite the kidneys; and if it was inverted so the groove is opposite the heart or its back opposite the cut — treifah; but if the groove is slightly inverted opposite the ona or below toward the ama — kosher — end of his words Mahariu, brought there in Darkei Moshe; and see his explanation in later slaughter examinations; and Maharshal Piskei Tosafot siman 31 wrote: what of it if the groove is inverted — this is only loss of Jewish money and one should abolish the custom — end:"]`,
  '2#ח': `["<b>And likewise if it changed its designation and form, etc.</b> Thus Igur siman 1000 section 110: if it has no groove like the designation of ayinunita de-varda — treifah; and if it is too large like the ona adjacent to the ama, or if it changed its designation that every varda has, or if it is less than a myrtle leaf in inflation — treifah; the word "designation" means its usual form; and if so, when it is drawn out and sharp like an ona and not round — one should declare treifah — end of his words; and Beit Yosef and Maharshal there siman 31 bring it; and from the words of Tosafot Piskei Tosafot (daf 47a) and Mordechai regarding ayinunita of every snake — their baraita is thus — it appears that if it changed its designation in a matter that even if it is only as large as one of the other onot — treifah; and so the Agudah and Rashba in his chiddushim there; and so Maharshal in his examinations that he heard in the name of a certain old wise man that if it is large even like the middle ona of the right — treifah; and so is implied in the signs of Maharshal Piskei Tosafot siman 31 who wrote: and if it is too large — treifah; and since he did not give a measure, evidently any change in its size is treifah; and so appears the view of the Rabbenu who wrote simply that if it changed its designation — treifah; however I have seen many examiners lenient in this and do not declare treifah except when it is as large as the ona adjacent to the ama; and so is the view of Mahariu; and it appears that even according to those who permit extra from the front in seif 3, nevertheless if it changed its designation and is so large — treifah, for it is like a missing varda, for this is an ona and not a varda; and so is the view of the Rabbenu:"]`,
  '2#ט': `["<b>Like finger-thickness, etc.</b> It implies that one always measures finger-thickness both in a small animal and in a large one; and so concludes Darkei Moshe; and so Maharshal there siman 32, unlike Yash who wrote that in a large animal we require two fingers; and likewise below siman 47 regarding two intestines emerging from one place that we require they have one root like finger-thickness — one does not distinguish between small and large, for once finger-thickness is called one root, the same applies in a large animal:"]`,
  '2#י': `["<b>Even though a crack settled in it.</b> Meaning: in the remaining root; and so Darkei Moshe:"]`,
  '2#כ': `["<b>And if one is inverted, etc.</b> Since it is adjacent to that they have one root — it refers to that; but if they do not have one root, it is obvious that even if both are not inverted it is treifah, for these are two vardot; and so is implied explicitly in Hagahot HaRav there — see there:"]`,
  '2#ל': `["<b>We follow the larger one, and if it is not inverted, etc.</b> Since he did not state "if inverted we follow the larger," and wrote "if it is inverted — treifah," it implies the same when both are equal — treifah; and so Darkei Moshe brought in the name of ancient examinations who wrote in the name of some that it is not kosher unless the inverted one is smaller than the non-inverted; and Darkei Moshe concluded there: and such a case already came before me and I permitted because the small one was inverted — end, unlike HaRav who was still in doubt about this; it also appears there from the words of HaRav that "changed its designation" has the law of inverted in this — see there:"]`,
  '2#מ': `["<b>And if no pouch was found for it, etc.</b> And Maharshal there ruled that even if it has no pouch at all — kosher; and all the more if it has two pouches or is not placed in a pouch; also in the responsum of Ma'aseh Binyamin siman 61 he agreed with Maharshal, except that he wrote: since they already practiced in these lands to forbid when the pouch is missing or it is not placed in the pouch — one should not change the custom, for it should not be like permitted matters that others practiced as forbidden, etc.; however regarding two pouches found he elaborated to permit — see there, for his words are correct, except that all examiners practice to declare treifah; and so in examinations of HaRav and Maharam, for such is the practice, and it is difficult to be lenient against the custom unless in great financial loss — and such is the case:"]`,
  '2#נ': `["<b>Or if it has two pouches, etc.</b> HaRav brings the language of Rosh of Ziria himself that specifically extra on the right side is considered as removed (for from the left side — kosher) — end of his words; and he wrote that such is practiced in the community of Krakow; and he brings Maharam in Sefer Machazik Brachah; and so Bach in this section; and Maharam wrote there: and it appears to me that specifically when the pouch on the left has no part of the varda, for otherwise it is forbidden on account of extra varda — end of his words; and it is simple; and see in s.k. 17 what Bach wrote:"]`,
  '2#ס': `["<b>And it is not placed, etc., and even when they place, etc.</b> Meaning: that it has a pouch and is not placed inside it — that is, even when they place it inside it comes back out when they inflate the lung — and it is simple; and the reason for this the acharonim wrote: because then it certainly changed its place slightly:"]`,
  '2#ע': `["<b>And all these laws, etc.</b> The words of Beit Yosef; but according to those who permit, extra anywhere it is found except on its back; and likewise according to those who permit two vardot, etc. — also all these exchanges are kosher — end of his words; and Darkei Moshe brings it; and wrote on it: and I already wrote that we practice in these lands to declare treifah any extra that is not literally in the row of onot — if so one should practice in all matters, etc. — end; it appears he also holds that according to those who permit extra from the front, everything is kosher; and if so it is astonishing that in seif 3 he wrote in the hagahah that in these lands they practice to permit extra from the front, and here wrote that in these lands all the stringencies — and so is indeed the custom in all these lands to permit extra from the front and to declare treifah for two vardot with all related stringencies; and so is found in all later examinations; and the matter that above, and so Rashi Piskei Tosafot (daf 47) explicitly that two ayinunita de-varda — treifah because it is extra from the front; and so is implied from the words of Shach and one must say there is a printing error in Darkei Moshe, for otherwise it is difficult: how did he write there that in these lands they practice to declare treifah extra not literally in the row of onot, yet in the hagahah seif 3 he wrote they practice to permit — and so is indeed the custom; and further: how did he write "and I already wrote," etc., yet he did not write this earlier in Darkei Moshe but afterward wrote the law of extra from the front — see there; rather there is a printing error and it must read: and I already wrote that we practice to declare treifah any extra varda — if so one should practice, etc.; and the Rabbenu holds that extra varda does not depend on extra from the front, as Mordechai and Hagahot Maimoni understood that Rambam's view is to declare treifah extra varda even though he wrote explicitly extra from the front is kosher; and so is the view of Mahariu: regarding extra varda he wrote plainly they practice to declare treifah, and regarding extra from the front he wrote there are those who permit — and according to this all the acharonim followed; and the reason appears to me that Chazal established that extra from the front is not considered extra at all, for such is the way in animals; but extra varda is not their way thus. And the distinction by which we know which is extra varda and which is extra from the front: when it has the true designation and form of a varda, even if the extra stands on the left side — it is extra varda, for it appears to the eye that there are two vardot; but when it does not have a true varda designation in a matter that can be considered extra, one may permit since it does not stand in the place of the varda; and so is implied in the responsum of Mahariu siman 97; and so in Hagahot HaRav there; and Maharam in Beit Yosef challenged him from the words of Tur who wrote in the name of Rosh: ayinunita on the left — treifah; and his conclusion: therefore one should not practice thus in a place where they practiced prohibition for two vardot — end; and he was not precise, for Rosh and Tur follow their reason who forbid extra from the front, for regarding varda they permit whether two vardot are found or none at all is found; and perhaps Maharam did not challenge him except according to what he understood from the words of HaRav that it has a true varda designation; and it is possible that for the law he agrees with what I explained; and likewise even if it does not stand in its place and has no true varda designation but has a pouch by itself — it is recognizable that there are two vardot and it is treifah; and so is implied from the words of Maharam that I brought in s.k. 15 and s.k. 20; but if it has no varda designation at all, even though it has a pouch — kosher; and so Bach in this section: such a case came before him several times and he permitted; if it stands in the place of the varda itself I received from the mouth of the Gaon my master may he live long that they practice to declare treifah if it has some varda designation; but if it resembles an ona itself one may consider it extra from the front; and if they have one root — its law was explained in s.k. 12:"]`,
  '2#פ': `["<b>One should examine the onot, etc.</b> R' Liberman the slaughterer of Prague wrote in his examinations: ayinunita requires varda designation, and if it has no varda designation it does not matter according to Mahariu who wrote: if the varda is missing somewhat and that piece is found in an ona or in the ama — kosher; and if a piece is missing, automatically it has no varda designation as explained — end; and one may sharpen against him: if so he fed Israel treifot all his days, for it was already explained in s.k. 9 that all poskim and all acharonim agreed that if it has no varda designation — treifah; and so the Rabbenu himself; and if one may conceive rejecting one law because of another, more so one should reject this law that is not mentioned in any posek — only the Rabbenu found it written, and it is a great leniency; also the Rabbenu wrote in Darkei Moshe on this law that it is astonishing; and if it is a received tradition — we accept it, and not reject the law of "changed its designation" which is explained in all poskim and is to be stringent; but in truth these laws do not contradict each other at all, for I received from the Gaon my master may he live long: when part of the varda is missing and it is found thus in an ona or in the ama, then they combine together and it appears to the eye that there is varda designation between both; and such is the case Maharam wrote in Machazik Brachah: if two vardot are found with one root that is not of finger-thickness measure and has no varda designation except through combination — they permit, for it is considered one — see there; and further that in what remains there is varda designation, as the Rabbenu wrote; and so there are those who permit if it has varda designation at its root, etc.:"]`,
  '2#צ': `["<b>From the left side.</b> Torat Chaim Piskei Tosafot wrote there is a printing error and it must read: from the right side, for if ayinunita is found on the left side — treifah, etc. — see there; and this is the explanation: for even according to his words it is still difficult, for the Rabbenu ruled that even on the right if it changed its place slightly — treifah, as I wrote in s.k. 8; and further, for in Darkei Moshe and in all later examinations and in Pri Megadim it also says from the left side; rather it is simple that this refers not to ayinunita found on the left side — here the root stands in the proper place but the head of the ayinunita is missing somewhat; and such is usual to find on the left side — and this is what our rabbis meant; and so a case came before me several times:"]`,
  '2#ק': `["<b>For thus is sometimes found in kids and lambs, etc.</b> The language implies at first glance that even in a large animal the law is thus, since it is usual to find thus in kids and lambs; but in the gloss that HaRav brought it states: and specifically in kids and lambs, for thus is sometimes found in kids and lambs; and regarding the law HaRav wrote there on this: but we do not practice thus except that in every change of place we declare treifah, whether kid or lamb; and so Maharam in Machazik Brachah: from the Rabbenu's language it appears there is no clear basis to permit; and it appears the reason: since it is attached to the ama it is merely extra, and the ayinunita has nothing; and if there is a pouch on it — then it is certainly a varda; but it is a varda by itself — end:"]`,
  '2#ר': `["<b>And likewise there are those who permit if it has varda designation, etc.</b> Thus HaRav: here in the community of Krakow they practice that if the ayinunita became small, only the root is recognizable — kosher, etc., for since the root is like thumb finger-thickness, even though it has no varda designation — nevertheless kosher; and so I saw, my master may he live long, to permit; and so in Beit Din siman 35 — end of his words; and he means Beit Din siman 35 in the words of the Rabbenu (certainly he does not mean Orach Chaim 14, for these laws were not mentioned there at all); and Maharam in his Beit Yosef challenged him that it is not found in Beit Din thus — see there, where he elaborated on this and labored in vain; also he elaborated there to refute HaRav's reason and his conclusion: since his reason is void, the law is also void; and it is not clear, for even though his words are correct to refute his reason, nevertheless there is another reason: since there is a root, the entire varda remains, and the law is a true law; and in truth these words of the Rabbenu were hidden from them:"]`,
  '2#ש': `["<b>And all these matters may be treated leniently, etc.</b> Maharshal wrote in examinations: all that they wrote to be lenient, whether in exchanges not mentioned in the Talmud or in the size of ayinunita de-varda — that is only when there is no other suspicious matter in another matter; but if there is another suspicious matter, even in a matter we permit, nevertheless since there is a side of stringency to declare treifah for someone, even not according to the law, nevertheless in anything it combines to support the forbidders, and we say it is a weakness and treifah — so it appears to me — end; and such is the case HaRav wrote regarding a case that came before him of a sheep with two pouches — see there:"]`,
  '3#א': `["<b>And when they inflate it, etc.</b> From the words of Magid Commentary that Beit Yosef brought and from the words of Mordechai that HaRav brought — it appears that since extra was found, one must inflate it and see whether it leans forward or toward the back; and on this see siman 39:"]`,
  '3#ב': `["<b>And if it leans toward the back — treifah.</b> And Beit Yosef and Darkei Moshe in the name of Magid Commentary: specifically a protruding extra lobe, but if it bent and goes upward there is no house of concern here, since it stands in a permitted place — because it protrudes outward it is not declared treifah — end of his words; and so HaRav brought in the name of Mordechai; and so is implied from the words of Maharam of Medellin that HaRav brought there; and so Pri Megadim; and he explained: protruding extra means like tarfa de-asa, even though it is rooted in the row of onot, etc. — see there; and so HaRav explained there; and so is in other acharonim:"]`,
  '3#ג': `["<b>And one should not change the custom.</b> See s.k. 17:"]`,
  '4#_': `Kosher. Even those who forbid extra from the front permit this, because this one stands in the row of onot and is called as Rashi wrote "the ona adjacent to the ama" — end Beit Yosef; and so Maharshal siman 34; and see above s.k. 47.`,
  '5#א': `["<b>Like tarfa de-asa.</b> And likewise even more than tarfa de-asa; and so Mahariu wrote:"]`,
  '5#ב': `["<b>Because its way is to split.</b> Because of the narrowness of the chest:"]`,
  '5#ג': `["<b>But not the left one.</b> And so Maharshal there siman 29; and Beit Yosef brings it; and so Darkei Moshe; and so HaRav: such is the practice:"]`,
  '5#ד': `["<b>And there is one who says: specifically above half of it.</b> Meaning: toward the tip of the ona; and so Mahariu, brought in Darkei Moshe:"]`,
  '5#ה': `["<b>But if they are equal on each side, etc.</b> And Mahariu wrote in hagahah: if there are five on each side — treifah; and Maharshal there wrote: and according to my view it is not in what is found, but if it is found may it be His will it come before me and I will buy from it the finest of the fine, for certainly one of the examiners invented this from his heart — end; and so Bach:"]`,
  '5#ו': `["<b>Like a crack combines to permit.</b> As I wrote in seif 8 — see there:"]`,
  '5#ז': `["<b>But not to declare treifah.</b> For if three onot are found on the left side and a crack — it is not like four onot; and it implies that even one healthy one combines to permit and not to declare treifah — for example if on the left side there is one ona and three cracks, we say one crack helps to permit and the others count for nothing to consider it exchange; and we do not say either way: if we count the crack as an ona it is exchange, for there are four on the left and three on the right; rather we are not concerned about cracks at all to declare treifah; and so is implied in the examination of HaRav; and with this one may resolve what the Rabbenu wrote here that a crack helps to permit, for at first glance it is superfluous, for it is explained in seif 8; rather as I explained:"]`,
  '5#ח': `["<b>It is counted only as one.</b> Meaning: to declare treifah; but to permit it is obvious it is no worse than permitting a crack in seif 8:"]`,
  '5#ט': `["<b>That it is not sharp at its head.</b> The words of Beit Yosef and Darkei Moshe in the name of Magid Commentary; and if above or below it is sharp like a cap — it is extra and treifah — end; and so HaRav wrote in the name of Mordechai; and see in later examinations:"]`,
  '5#י': `["<b>Except when they place the hand gently on it, etc.</b> So Darkei Moshe: such a case came before me and I permitted it; and so agreed most experts in the city, for the reason it is kosher when there is a hollow there is because it has a place to rest and does not rub itself against the walls of the lung and is not destined to come apart or be perforated; and likewise here, since when they place the hand on it gently it descends into the hollow — the same applies when it reaches the animal's walls it descends into the hollow and need not rub; and behold one of the experts did for me on that lung another split like the first and there was a hollow beneath it, and when they inflated the lung it also rose somewhat because of the inflation and descended when they touched it gently with the hand; therefore we agreed to permit, for this is a baraita — end Darkei Moshe:"]`,
  '5#כ': `["<b>But from the front the split, etc.</b> And some hold: extra from the front is kosher, for there the extra is of the ona and did not split from the body of the lung and it is strong; but a split that split from the body of the lung where there is a hollow beneath it, and when they turn the lung the split falls into the hollow — then it appears it split from the body of the lung and is not strong and will eventually come apart and is treifah, as explained — end; unlike Maharam in Machazik Brachah who wrote the Rabbenu deals with a place where they forbid extra from the front, and so they practice to permit extra from the front and to declare treifah a split from the front — and this is from the reason I explained:"]`,
  '5#ל': `["<b>Extra opposite the groove of the varda, etc.</b> Meaning: beneath the varda opposite the groove; and so is in Darkei Moshe; and some disqualify extra from the front; therefore they needed to permit through the protection of the groove; and the Rabbenu challenged them: if extra is treifah, the same applies to this; and so is implied explicitly in Darkei Moshe; and the practical difference: in a place where they forbid extra from the front one may not permit this except in a time of distress; but in a place where they permit extra from the front it is obvious that this too is kosher; and so in Machazik Brachah:"]`,
  '5#מ': `["<b>And one should not rely on this except in a time of distress and great loss.</b> So it must read; and so is in Pri Megadim; thus Darkei Moshe: and it appears to me that some hold a split with a hollow beneath is different, for the reason of the hollow is not protection alone, but that if it fell inside the hollow it would not be extra at all but split from the lung; therefore the hollow remains beneath it, as I wrote that one expert made one split and a hollow beneath it before me and therefore it is kosher; but in other extra — what does protection of the groove help? If we say all extra is considered as removed, therefore it appears one should not rely on this reason; nevertheless one who is lenient did not lose, for many geonim permit extra from the front — end:"]`,
  '6#_': `Less than a myrtle leaf. See above s.k. 7.`,
  '7#א': `["<b>From the onot of the right.</b> And Beit Yosef; but if missing on the left, even if varda is found on the left it does not complete — so all hold; and Bach disagreed — see there:"]`,
  '7#ב': `["<b>The varda completes, and some say, etc.</b> Beit Yosef and Perishah and Bach wrote: the reason for their dispute — Rambam and his supporters follow their reason who permit extra from the front, evidently extra from the front and the row of onot are one matter; and Rashi and his supporters follow their reason who declare extra from the front treifah — end; and accordingly all the more if no varda is found at all, only extra from the front — it completes for the Mechaber and his supporters; and accordingly the Rabbenu who wrote such is the custom like Rashi and his supporters — not from their reason, for they declare extra from the front treifah, and the Rabbenu in seif 3 wrote they practice to permit extra from the front; and "one should not change the custom" refers only to the reason that we hold missing varda is treifah — if so, if it combines to an ona it is missing; and so is explained in the examination of HaRav in the name of the Rav and R' Avigdor; and accordingly if extra of an ona from the front is in the manner I wrote in s.k. 17 — it completes for all; however it is difficult accordingly: if so, that which the Rabbenu wrote "and some say it does not complete" — that is from the reason they disqualify extra from the front, and immediately he says "and such is the custom" from another reason; also Darkei Moshe did not mention another reason at all. And it appears the Rav did not hold as Beit Yosef and his supporters, but held the reason of the poskim that it does not complete is because they hold that since they do not stand literally in the row of onot they do not complete the deficiency; and so is implied from the words of the Rav that HaRav brought there, who wrote: it may be that it does not combine even though if the varda is missing it is kosher — end, meaning nevertheless it does not combine since it does not stand literally in the row of onot (and Maharam in Sdei Chemed challenged HaRav on this not according to law in matters that are not correct — see there); and so is implied explicitly in Pri Megadim; and so is implied in Igur that he brought in his conclusion the words of Tur: when the varda is missing or extra — kosher; and afterward he brought in his conclusion the words of those who permit extra from the front; and afterward he brought in his conclusion the words of Semak that it does not complete the varda for a missing ona — examine; and accordingly even extra of an ona does not complete — for example if the varda is as it should be and there is also extra from the front with it — it does not complete for us:"]`,
  '8#א': `["<b>And if a crack, etc.</b> And Mahariu wrote: specifically when the crack stands in its proper place; but other cracks do not help — end; and Maharshal Piskei Tosafot siman 35 brings it:"]`,
  '8#ב': `["<b>And there are those who permit with a sign or any crack, etc.</b> And Maharshal there wrote: and I say like the words of Rambam, and according to my view even Rashi agrees with him, for what does a sign or crack help? Perhaps there is a deficiency in an ona; it is fine where it resembles a sponge that is entirely attached — then where there is some sign we see that thus they grew; but for one or two missing onot one may not permit with a sign or crack unless there is a distinction of the measure of an ona — that is, like tarfa de-asa — end; and in the words of Rashba and Ran and Mordechai and Hagahot Ashiri and Tur it appears explicitly one should not distinguish between entirely attached and one or two onot; and so from the words of Beit Yosef and from his words here; and so from the words of the Rabbenu in Darkei Moshe and in the hagahah; also according to what Ran wrote that Rashi's reason is since there is a sign it appears there is no deficiency but they stuck in order — it is explained there is no distinction; and now there is no difficulty from what Maharshal wrote "what does a sign help — ultimately there is deficiency in an ona," for since there is a sign it appears the onot were as they should be but stuck in order and there is no deficiency; also there is no logic at all to distinguish thus — examine; and so Bach ruled:"]`,
  '8#ג': `["<b>The lower ona, etc.</b> And Maharshal there disagrees with all this and wrote: and I say that no sign helps to prove that the onot are attached — what of it if they are attached, and why is it invalid? It resembles a sponge and does not leave the category of sponge unless with a sign of crack and cut of the onot; and all the more what the expert examiners say, that each ona has a furrow (simpun) by itself — if so we see after the furrows whether they are as they should be and in their place they permit even without a crack; and again I found thus in a gloss in the name of Maharach — and it is not clear, even though the experts say they received thus as he explained — end; and perhaps Maharshal spoke only when the entire ama is attached; but when the lung is as it should be except two onot are attached — such may be permitted through simpun, for now we do not come on it from the reason it resembles a sponge but from the reason of missing, and since there is a simpun it appears there was an ona by itself but stuck in order; and so Maharam in Machazik Brachah: the words of Maharach apply specifically to two onot, but not to an entire attached ama — see there; and this is what the Rabbenu wrote: through the furrow usual to be in an ona; and so in the words of Maharach brought in Darkei Moshe; and Ran states: two attached onot, etc., if they have two furrows, etc.; and it is possible that the sign of long and thick that Mahariu and the Rabbenu mention is also in such a case, for the entire lung is as it should be except the lower ona is attached; and even though Maharshal's words appear to forbid in every matter, for his language implies he challenges even Maharach who deals with two onot — nevertheless since in this his reason is hidden and the Rabbenu holds thus and so practiced all examiners and so is found in all later examinations, one should not be stringent; but when the entire lung is attached — in this certainly one may not permit through simpun, only through sign of crack and cut, as explained:"]`,
  '8#ד': `["<b>Some say: in kids and lambs, etc.</b> And Machazik Brachah wrote: it must mean specifically when it has no sign of onot at all; but if one side has and the other does not — it appears it has the law of sponge like adults; and it appears to me they are not called tender for this purpose except within thirty days of birth; and also they follow the mother who nurses them, for we find regarding firstborn that they are not called lambs to graze with their owners until given to priests only until thirty days; but after thirty days, even though they follow the mother and she nurses them, nevertheless they are considered as adults — so it appears to me — end; and from the simple sense we say this is after thirty days, for this itself is a great leniency in a matter not found in Talmud and poskim; and they gave it lest we add upon it except when we know certainly it is within thirty days, but from doubt — forbidden:"]`,
  '9#_': `And there are those who practice to declare treifah. And so HaRav and other acharonim that such is the practice; and Bach wrote: some disagree with what was written in seif 4 that an extra ona found at the end of the slopes of the ama is kosher; and so in the hagahah: this is called in the row of onot (and so HaRav) — it is different there, for the onot are as they should be and in our count; and if so this protrusion is no worse than other extra standing in the row of onot; but for one missing ona this protrusion does not complete the deficiency; and so Maharshal divides Piskei Tosafot siman 34; and in Ma'adanei Melech he left this in need of further study.`,
});

patchFile('siman_035/turei-zahav/part-001.txt', 'turei-zahav', {
  '2#א': `Onot. Its meaning is language of ear; and ama — language of mother, meaning the large one from which the onot separate and it is the main lung — so Rosh wrote. Ayinunita de-varda: meaning a small ona of varda, on account of its delicacy and redness — Rashi.`,
  '2#ב': `The forms of the onot, etc. These laws in this hagahah Maharshal brought and wrote on them: and I am astonished what basis there is for these exchanges and to add treifos on what was not mentioned in the Talmud even by hint, for it only said five onot the lung has — three on the right and two on the left; but all these distinctions — who mentioned them that exchange should apply to them? This is only destruction of Jewish money — end. And my master may he live long wrote: and nevertheless, where there is no great financial loss, one should not rule permission in what they practiced as forbidden, even though by law there is no prohibition — end. And Maharshal wrote in the name of examinations: if the varda is larger than the ona next to it — meaning the ona adjacent to the ama — treifah; and he wrote well, for its name is ayinunita, and if it is so large that name does not apply — end his words. He also wrote: if the ama is above and the onot below — treifah; and it appears to me that where there is another suspicious matter, even though one does not declare treifah on its account, nevertheless it combines with the suspicious matter above and treifah.`,
  '2#ג': `And the varda: if missing, etc. The reason: since in some animals there is and in some there is not, one should not declare treifah for any change of vardot. Changed its designation and form — Maharshal explained: when it is drawn out like an ona and not round — certainly for an ona there is no concern if it is not drawn and sharp, for only regarding ayinunita do we say changed designation is treifah, for treifos laws depend on the ways of lung growth, and Chazal established that an ona is sometimes round and sometimes sharp, but varda's law is round — end Igur. And he also wrote: if the ayinunita is entirely round without a groove — treifah, for its designation is known and according to its designation they called it by this name — end.`,
  '2#ד': `Whether two vardot are found, etc. At first glance it is difficult: for Rama wrote in seif 3 that our custom is to permit all extra from the front; and it appears here the disqualification is not on account of extra but since there is extra and all extra is considered as removed — if so the varda that should be there is missing; and likewise changed place — meaning it stands on the left side; and Tur wrote in the name of Rosh that it is treifah because of extra; and accordingly we should have permitted, for this is extra from the front; except that we forbid this because the varda is missing in the place where it should be; and accordingly treifos of varda are only when both are in the place of the varda and do not have one root like finger-thickness after inflation; nevertheless if you find an extra ona inside, even in the place where the varda should be, there is no disqualification for two vardot, for the form of the ona is not like a varda, as Tosafot wrote in chapter Eizehu Mekoman regarding that "between and between," etc.; and the same if two vardot are found, one on the right and one on the left — "extra as removed" does not apply since the extra does not stand in its proper place — compare extra of the leg siman 55 seif 4; and from the reason of extra there is no disqualification, for it is from the front and Rama already testified that the custom is to permit all extra from the front — implying even not in the row of onot, as explained.`,
  '2#ה': `One root. Magid Commentary in the name of Or Zaru'a: even though there is no finger-thickness there; and a certain sage wrote: nevertheless we require the length of the root like a finger between the two vardot; and it appears to me the measure of the height of the root of both before they branch must be like a finger.`,
  '2#ו': `And all these matters, etc. This does not refer to what was said regarding missing or two vardot or changed place — these treifos were mentioned in Rashi and Tosafot Piskei Tosafot; rather it refers to the other laws mentioned in the hagahah. And Maharshal wrote to permit the laws forbidden on account of the pouch that Rama mentioned, for the pouch was not mentioned in the Gemara; and regarding changed designation I already wrote shortly in his name that it is treifah; and regarding the law of inverted that Rama mentioned here — treifah when the varda is inverted — meaning its way is that it has a groove aligned opposite the cut between ona and ama, its back opposite the heart and its face opposite the kidneys; and if inverted, such as the groove opposite the heart and its back opposite the cut — treifah, as written in our examinations; and Maharshal wrote on this: for this there is no reason or smell, since it did not change its form or place, only the groove is inverted — what of it? This is only loss of Jewish money; and if my effort succeeds I would abolish it — end.`,
  '4#_': `For this is called in the row of onot. See what I wrote in seif 9 from this.`,
  '5#א': `That specifically above half, etc. In the examinations of Mahariu he brought on this two explanations: one — the half is toward the tip of the ona; but if found toward the root of the ona — treifah; and accordingly the measure of half is in the width of the ona. And some say one also measures in the length of the ona — that half in width that we permitted is not all of it but specifically half its length — that is, opposite the windpipe, but not the other half toward the lung — end Mahariu's words; and so I saw Maharshal explained, and one should be stringent like the latter view.`,
  '5#ב': `In each side three or four, etc. Maharshal wrote: what he wrote in Likutim that one may not permit only up to ten onot on both sides — that is, five on each side and no more — is the view of one who startles, and if it comes before me I will buy the finest from it.`,
  '5#ג': `Combines. In the hagahah of Hagahot Ashiri: an incident where on the right were two large onot and the third was recognizable by a cut to permit through it, and there was another change that on the left there were three onot; and Rav Achai forbade and R' Yosef answered: I do not know why he forbade unless he received from his teachers, for it appears to me complete permission — end; and Maharshal wrote: it appears to be stringent like Rav Achai's teachers, and it appears Rama is also stringent here, for there are two suspicious matters.`,
  '5#ד': `It is called a lump and kosher. And if above or below sharp like a cap — treifah — Beit Yosef; and Magid Commentary wrote: if it is wide below and round above — kosher.`,
  '5#ה': `And equal to the rest of the lung. It implies that if it was shorter than the hollow — treifah, for then it is not a split but extra.`,
  '5#ו': `But from the front, etc. Meaning: if there is a split with a hollow beneath it, we say since when it began to split it will eventually come apart entirely; but if there is no hollow there, it was explained above that our custom is to permit extra from the front. If extra is found in a bed above the onot adjacent to the spine inside the lung — it is kosher; and it appears to me treifah, for this is certainly included more in "on its back" mentioned in the Talmud than what is included inside.`,
  '8#א': `That it has no cut of a lobe. Maharshal wrote in the name of a certain hagahah: there was an incident in Rinus where they slaughtered a fat cow and when examined found no lung — neither ama nor ona nor varda nor crack, only smooth like one piece of meat; and one examiner prominent among the sages of Austria took a sharp knife, cut the upper membrane, opened gently, peeled gently, separated it all — then they saw the lung like other lungs and permitted it; he said he saw such in Austria; the sages of Austria permitted it — see what I wrote end of section 39.`,
  '8#ב': `And if it is entirely attached to the ama, etc. In Hagahot HaRav he wrote to distinguish: specifically from ona to ama we say thus, but not from ona to ona — there these signs do not help; and other hagahot disagree that their law is equal, and such is primary.`,
  '8#ג': `In youth they do not have them. Accordingly it appears: if on one side they have cuts of onot and on the other they do not — treifah, for here one cannot say because of youth they do not have them.`,
  '9#_': `Below the varda is called not in the row of onot. At first glance one should forbid also that of seif 4 for this reason; but Rama's language does not imply any distinction; and the reason appears: there it is kosher either way — if it were in the row of onot it is obviously kosher; and if not in the row of onot, because the varda divides and completes the count of the onot, nevertheless kosher because it is not on its back, as Beit Yosef wrote; unlike when there is clearly a missing ona before you and you need to complete it with a clear replacement — perhaps it is called not in the row of onot and there is no valid replacement; and so I saw Maharshal ruled here to forbid and that of seif 4 to permit. My master may he live long wrote: a case came before him several times — a lung with no suspicious matter except on the left a protrusion from the ama at the cut between ona and ama exactly where the varda usually stands opposite on the right; that protrusion had a complete pouch, was placed in it, had no varda form at all, and was equal to the ama on the front as if cut from it; he permitted because that protrusion was neither extra from the front nor extra varda and there is no suspicious matter except from the pouch — end. And it appears to me even if it had varda form there is no prohibition, for it is called extra from the front and kosher for us; prohibition of two vardot is only when both stand on the right in their proper place and are not like finger-thickness between them, as written above; and the pouch certainly does not forbid, for we do not find that because of a pouch extra there is prohibition, as explained. Maharshal wrote: if the lung's extra stands in the row of onot and leans slightly outward through inflation — treifah; but Beit Yosef wrote: specifically protruding extra, but if bent and goes upward — kosher since rooted in a permitted place — end.`,
});

patchFile('siman_035/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 35 seif 2 in the hagahah b') If two vardot are found in it, etc., and if one is inverted and the other is not inverted — we follow the larger, and if it is not inverted — kosher. Shach wrote: "that they have one root" refers — for if they do not have one root, in any case treifah because of two vardot; it is proven from his words that even if one stands not in its place, these are two vardot, and even though it is inverted, nevertheless it has varda designation and pouch. According to his reason: he wrote in s.k. 17 that two vardot where one stands on the left side is treifah if it has varda designation as it should be, and even partially if it has a pouch — in his view this is extra stringency; and it appears to me explicitly in Hagahot Ashiri and Tur in the name of R' Yitzchak ibn Chaviv that ayinunita on the left is considered an extra ona and not a varda, since it changed its place; if so, for us it is extra from the front, which we practice to permit, as the hagahah seif 3 wrote. And so one may prove from Tosafot Piskei Tosafot (daf 47) and Ran and Mordechai who wrote: that which we say "between and between" is treifah means where it is very large and not similar to ayinunita de-varda — evidently when there is a change that it is not similar to ayinunita de-varda, it is extra ona, and for us kosher; therefore it appears to me that even if one is stringent with two vardot where one stands on the left when it has true varda designation, nevertheless when it has some change one should not be stringent, as implied from Tosafot, Rosh, Ran, Mordechai, Tur, Beit Yosef, and R' Yitzchak ibn Chaviv; and all the more Taz and Pri Chadash are lenient with two vardot where one stands on the left. And accordingly the words of the hagahah are well explained according to their plain sense: if two vardot are found, etc., it properly deals when they do not have one root, but one stands distant and is judged as extra from the front because of the change that it is inverted — examine. And in responsum Be'er Yaakov he wrote: in great financial loss one may permit the inverted one; and if the pouch was perforated, Pri Megadim permits; and so Bach in this section 39. However what Pri Megadim wrote — proof from adhesion siman 39 — is not proof for perforation, as stated siman 41 regarding liver fat, for treifos of pouch are not on their own account but because of the varda; if so, sealing helps; and so Bach implies; if so, there is no proof for perforation; nevertheless it appears that since those who forbid mentioned only missing and extra, and the default is perforation is not included, as proven siman 50 — see what I wrote siman 45: if the small one was perforated or adhered — one may not permit; and see there the reason. And the large one — Bach forbids for changing its place slightly, since this treifah was mentioned in Tosafot Piskei Tosafot; and this does not contradict siman 44 and responsum Tzitz Eliezer regarding liver, for there too we come because of perforation. And see in responsum Zichron Yosef regarding the milk of an animal whose varda was inverted — one may permit before twelve months, and in great financial loss one may permit even the animal; but when missing or extra varda is found — he forbids cheeses until twelve months, and before twelve months permitted either way, or it was made afterward; and if you say it was made from before — then the twelve-month wait of the permissive view for doubtful dispute helps, as those who permit regarding doubtful case.`,
  '2#_': `(Seif 5 in the hagahah) If an ona is found on the lung's surface and a hollow beneath it, etc., and equal to the rest of the lung, etc. — kosher. It does not appear to be extra but a split of the lung; and since it has a hollow beneath to rest in, it will not come apart like other extra; and when they place the hand gently on it — kosher. It implies we require both: it is not extra, and also it will not come apart; but if it were extra, what helps that it will not come apart — for example if the split were shorter than the hollow — treifah. And so Taz; and unlike Pri Chadash and Nekudot HaKesef who challenged him, since ultimately it will not come apart — see there. And I did not descend to the end of their minds: for if so, why for extra opposite the groove of the varda does the hagahah not permit except in distress and great loss — behold the groove protects the extra that it will not come apart; and Darkei Moshe states explicitly he does not permit except because otherwise there are those who permit extra from the front, but without this he would not permit because it will not come apart, since it is extra, and we hold all extra is considered as removed; and so explicitly Mahariu, source of this law, brought in Darkei Moshe: and it must fill the hollow and not be wider — end; it is clear: if the split is shorter than the hollow so it does not fill it and the hollow is wider and taller — treifah, for then it is not a split but extra, and all extra is considered as removed. And further it appears a good reason: even if it were not extra, behold here there is a healthy hollow, for we hold in the hagahah siman 36 seif 8: if the deficiency is like a bent palm and one can place a thumb in this deficiency — treifah; and all the more here there are two suspicious matters — extra and missing — examine. And after I wrote this several years later, Sefer Torat Yekutiel came to my hand and I saw there like these words — it pleased me — may the Merciful save.`,
  '3#_': `(Seif 5 in the hagahah) The lower ona, etc. See in Shach what he divides: when the entire lung is attached, a sign does not help; but when two onot are attached, it helps. And accordingly it appears to me to resolve what they challenge on that which Ravya said it resembles sponge — treifah: why do we not derive it is missing an ona, which is treifah? And according to Shach's words for practical law: he deals when it has no cuts of onot, but there are these sign indications. And so one may say here on what Lechem Mishneh wrote chapter 10 of Laws of Shechitah section 8: the lung was missing from the count of onot and the lung was found without cuts of onot — and even though all the more it is missing an ona.`,
  '4#_': `(In the hagahah) Some say: in kids and lambs one should not declare treifah if onot are not found, etc., and when they grow the onot grow with them. An example for this is in chapter These Are Treifos (daf 65) and chapter One May Not Stand (daf 39) regarding signs of fish and locusts: even though it does not have them now and will grow them later — permitted; and so Tur ruled section 3 and section 5.`,
});

patchFile('siman_035/yad-ephraim/part-001.txt', 'yad-ephraim', {
  '1#_': `(Siman 35, Taz s.k. 2) If the varda is larger than the ona. In Shach s.k. 9 he wrote in the name of Maharshal in examinations: even if large like an ona — treifah; and see Shach s.k. 22.`,
  '2#_': `(In the introduction) And it appears to me that in a place, etc. And so Maharshal himself, brought in Shach s.k. 22.`,
  '3#_': `(There s.k. 4) Except when both are in the place of the varda and are not like finger-thickness between them — Taz in this section.`,
  '4#_': `(Shach s.k. 8) Or its back — must read: and its back.`,
  '5#_': `(There s.k. 9) For it is like missing varda. In any case even for those who permit — missing varda; nevertheless treifah because it is extra ona; and in the row of varda, even with slight varda designation, those who permit do not permit — Shach s.k. 17: it is extra; examine.`,
  '6#_': `(Siman 35 seif 2 in the hagahah) One root like finger-thickness — meaning the width of the thumb at its wide place.`,
  '7#_': `(Taz s.k. 60) Must be like a finger. And in great financial loss it suffices that there be one root like a finger in its length; and so in its height. And without great financial loss, the entire length of one root must be like finger-thickness in its height.`,
  '8#_': `(Shach s.k. 15) But from the left side — kosher. It implies: on the right, even if the varda does not benefit from two pouches, nevertheless treifah; and specifically when the pouch has a lip at its mouth; but if it has no lip, it is only a protrusion and not called two pouches; nevertheless if varda is found without a lip, it is not called missing pouch — acharonim.`,
  '9#_': `(There s.k. 17) Because then it certainly changed its place slightly — meaning even those who permit missing pouch agree to this.`,
  '10#_': `(There s.k. 17) Even if the extra stands on the left side — meaning extra from the front on the left side; but literally in the row on the left side — kosher — Bach.`,
});

